# logscan.py
import sys
import os

def print_usage_and_exit(msg, exit_code):
    """Prints usage message to stderr and exits."""
    if msg:
        sys.stderr.write(f"{msg}\n")
    sys.stderr.write("usage: logscan.py PATH LEVEL [--at-least] [--limit N]\n")
    sys.exit(exit_code)

def get_level_rank(level_str):
    """Returns the rank of a log level. Lower rank means less severe."""
    levels = {"INFO": 1, "WARN": 2, "ERROR": 3}
    upper_level = level_str.upper()
    return levels.get(upper_level)

def parse_arguments():
    """
    Parses command-line arguments robustly, allowing options before or after
    positional arguments.
    """
    args = sys.argv[1:]

    path = None
    level_str = None
    options = {
        'at_least': False,
        'limit': None
    }

    # Since options can be anywhere, we iterate through all arguments
    i = 0
    while i < len(args):
        arg = args[i]

        if arg == '--at-least':
            options['at_least'] = True
            i += 1
        elif arg == '--limit':
            i += 1
            if i >= len(args):
                print_usage_and_exit("Missing value for --limit", 2)
            try:
                N = int(args[i])
                if N < 0:
                    print_usage_and_exit("Limit N must be non-negative", 2)
                options['limit'] = N
                i += 1
            except ValueError:
                print_usage_and_exit(f"Invalid value for --limit: {args[i]}", 2)
        elif arg.startswith('--'):
            # Unknown option
            print_usage_and_exit(f"Unknown option: {arg}", 2)
        else:
            # Treat as positional arguments (PATH or LEVEL)
            if path is None:
                path = arg
            elif level_str is None:
                level_str = arg
            else:
                # Too many positional arguments
                print_usage_and_exit(f"Too many positional arguments. Found: {arg}", 2)
            i += 1

    # Final validation for positional arguments
    if path is None:
        print_usage_and_exit("Missing required argument: PATH", 2)
    if level_str is None:
        print_usage_and_exit("Missing required argument: LEVEL", 2)

    # Validate target LEVEL now that it's parsed
    target_rank = get_level_rank(level_str)
    if target_rank is None:
        print_usage_and_exit(f"Invalid log level specified: {level_str}", 2)

    return path, level_str, options, target_rank

def compare_levels(line_level_rank, target_rank, at_least):
    """
    Compares a line's level to the target level based on severity order (INFO < WARN < ERROR).
    """
    if at_least:
        # Match if line level rank is equal to or greater than target rank (more severe or equal)
        return line_level_rank >= target_rank
    else:
        # Match only if levels are exactly equal
        return line_level_rank == target_rank

def process_log_file(path, target_level_str, options, target_rank):
    """Reads the file, matches lines, prints results, and prints count to stderr."""

    if not os.path.isfile(path):
        sys.stderr.write(f"logscan.py: cannot open {path}\n")
        sys.exit(1)

    try:
        with open(path, 'r', encoding='utf-8') as f:
            lines = f.readlines()
    except Exception:
        # Catch potential encoding/IO errors during reading
        sys.stderr.write(f"logscan.py: cannot open {path}\n")
        sys.exit(1)

    at_least = options['at_least']
    limit = options['limit']

    matching_lines = []

    for line in lines:
        # Log format: DATE TIME LEVEL MESSAGE
        # Split by whitespace to isolate the level field
        fields = line.strip().split()

        if len(fields) < 3:
            continue

        line_level_str = fields[2]
        line_rank = get_level_rank(line_level_str)

        if line_rank is not None:
            if compare_levels(line_rank, target_rank, at_least):
                matching_lines.append(line)

    # 1. Print matching lines up to the limit to stdout
    for i, line in enumerate(matching_lines):
        if limit is not None and i >= limit:
            break
        sys.stdout.write(line)

    # 2. Print total count to stderr
    total_matches = len(matching_lines)
    sys.stderr.write(f"count={total_matches}\n")

    # Exit status 0 is required regardless of matches
    sys.exit(0)


if __name__ == "__main__":
    try:
        # Parse arguments and get the target rank immediately for early validation
        path, level_str, options, target_rank = parse_arguments()

        # Process file
        process_log_file(path, level_str, options, target_rank)

    except SystemExit as e:
        # Propagate exit codes from usage errors (status 1 or 2)
        sys.exit(e.code)
    except Exception as e:
        # Catch any unexpected runtime errors not covered by specific exit paths
        sys.stderr.write(f"An unexpected error occurred: {e}\n")
        sys.exit(2)
