# semver.py

import re
from typing import Tuple, Union, List

# --- Internal Helpers and Constants ---

# SemVer 2.0.0 Regex components
# MAJOR, MINOR, PATCH: Non-negative integers without leading zeros (unless zero itself)
INTEGER_REGEX = r"(0|[1-9]\d*)"
# PRERELEASE identifier: Alphanumeric and hyphens, must be non-empty
IDENTIFIER_REGEX = r"[0-9A-Za-z-]+"
# Full pre-release tag: starts with '-', followed by dot-separated non-empty identifiers
PRERELEASE_TAG_REGEX = r"(-" + r"(?:" + IDENTIFIER_REGEX + r"(?:\." + IDENTIFIER_REGEX + r")*))"
# Full build metadata: starts with '+', followed by dot-separated identifiers (can be empty, but spec implies non-empty for identifiers)
BUILD_REGEX = r"(\+[0-9A-Za-]{1}(?:\.[0-9A-Za-]{1})*)"

# Full SemVer 2.0.0 pattern
SEMVER_REGEX = re.compile(
    rf"^({INTEGER_REGEX})\.({INTEGER_REGEX})\.({INTEGER_REGEX})"  # MAJOR.MINOR.PATCH
    rf"(?:{PRERELEASE_TAG_REGEX})?"  # Optional Pre-release
    rf"(?:{BUILD_REGEX})?$"          # Optional Build metadata
)

# --- Version Class ---

class Version:
    """
    Represents a Semantic Versioning 2.0.0 number and provides version range
    satisfaction logic.
    """
    def __init__(self, major: int, minor: int, patch: int, prerelease: Tuple[str, ...], build: Tuple[str, ...]):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease
        self.build = build

    @classmethod
    def parse(cls, text: str) -> 'Version':
        """
        Parses a full SemVer 2.0.0 string into a Version object.
        Raises ValueError on any parsing failure according to strict rules.
        """
        if not text or text.strip() != text:
            raise ValueError("Input must not contain surrounding whitespace.")

        match = SEMVER_REGEX.fullmatch(text)
        if not match:
            raise ValueError(f"Invalid SemVer format: {text}")

        major_str, minor_str, patch_str, prerelease_full, build_full = match.groups()

        major = int(major_str)
        minor = int(minor_str)
        patch = int(patch_str)

        # Leading zero check (redundant due to regex, but kept for explicitness)
        if (len(major_str) > 1 and major_str.startswith('0')) or \
           (len(minor_str) > 1 and minor_str.startswith('0')) or \
           (len(patch_str) > 1 and patch_str.startswith('0')):
            raise ValueError("Numeric components (MAJOR, MINOR, PATCH) cannot have leading zeros.")

        prerelease = ()
        build = ()

        if prerelease_full:
            # Remove the leading '-'
            tag = prerelease_full[1:]
            prerelease = tuple(tag.split('.'))

            # Check for empty identifiers (e.g., 1.2.3-a..b or 1.2.3-)
            if any(not id_part for id_part in prerelease):
                raise ValueError("Pre-release identifiers cannot be empty.")

            # Check for numeric pre-release identifier leading zeros
            for identifier in prerelease:
                if identifier.isdigit() and len(identifier) > 1 and identifier.startswith('0'):
                    raise ValueError("Numeric pre-release identifiers must not have leading zeros.")

        if build_full:
            # Remove the leading '+'
            tag = build_full[1:]
            build = tuple(tag.split('.'))

            # Check for empty identifiers in build metadata
            if any(not id_part for id_part in build):
                 raise ValueError("Build identifiers cannot be empty.")

        return cls(major, minor, patch, prerelease, build)

    def __str__(self) -> str:
        """Returns the canonical text the version was parsed from."""
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            s += f"-{'.'.join(self.prerelease)}"
        if self.build:
            s += f"+{'.'.join(self.build)}"
        return s

    def __repr__(self) -> str:
        return f"Version('{self.major}.{self.minor}.{self.patch}')"

    def __hash__(self) -> int:
        # Hash based on core components (ignoring build metadata)
        return hash((self.major, self.minor, self.patch, self.prerelease))

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented

        # Equality ignores build metadata
        return (self.major == other.major and
                self.minor == other.minor and
                self.patch == other.patch and
                self.prerelease == other.prerelease)

    def __ne__(self, other: object) -> bool:
        return not self.__eq__(other)

    def __lt__(self, other: object) -> bool:
        return self._compare(other) < 0

    def __le__(self, other: object) -> bool:
        return self._compare(other) <= 0

    def __gt__(self, other: object) -> bool:
        return self._compare(other) > 0

    def __ge__(self, other: object) -> bool:
        return self._compare(other) >= 0

    def _compare(self, other: 'Version') -> int:
        """
        Compares two Version objects according to SemVer precedence.
        Returns: -1 if self < other, 0 if self == other, 1 if self > other.
        """
        # 1. Compare MAJOR, MINOR, PATCH numerically
        if self.major != other.major:
            return 1 if self.major > other.major else -1
        if self.minor != other.minor:
            return 1 if self.minor > other.minor else -1
        if self.patch != other.patch:
            return 1 if self.patch > other.patch else -1

        # 2. Compare pre-release tags
        # A version without pre-release is always higher than one with pre-release
        if not self.prerelease and other.prerelease:
            return 1
        if self.prerelease and not other.prerelease:
            return -1

        if self.prerelease and other.prerelease:
            # Compare identifiers left-to-right
            len_s = len(self.prerelease)
            len_o = len(other.prerelease)

            for i in range(min(len_s, len_o)):
                id_s = self.prerelease[i]
                id_o = other.prerelease[i]

                is_num_s = id_s.isdigit()
                is_num_o = id_o.isdigit()

                if is_num_s and is_num_o:
                    num_s = int(id_s)
                    num_o = int(id_o)
                    if num_s != num_o:
                        return 1 if num_s > num_o else -1
                elif not is_num_s and not is_num_o:
                    # Alphanumeric comparison (ASCII order)
                    if id_s != id_o:
                        return 1 if id_s > id_o else -1
                elif is_num_s and not is_num_o:
                    # Numeric lower than alphanumeric
                    return -1
                elif not is_num_s and is_num_o:
                    return 1

            # If all common identifiers are equal, the shorter list is lower
            if len_s != len_o:
                return 1 if len_s > len_o else -1

            return 0 # Identical

        # 3. If both have no pre-release, they are equal (Build metadata ignored)
        return 0

    def bump(self, kind: str) -> 'Version':
        """
        Returns a new version bumped by the specified kind.
        The result always strips pre-release and build metadata.
        """
        kind = kind.lower()
        if kind == 'major':
            return Version(self.major + 1, 0, 0, (), ())
        elif kind == 'minor':
            return Version(self.major, self.minor + 1, 0, (), ())
        elif kind == 'patch':
            return Version(self.major, self.minor, self.patch + 1, (), ())
        else:
            raise ValueError(f"Invalid bump kind: '{kind}'. Must be 'major', 'minor', or 'patch'.")


# --- Range Checking Logic ---

def _parse_partial_version(v_str: str) -> Union[Version, None]:
    """
    Parses a partial version string (e.g., '1.2') into a canonical Version object (1.2.0).
    Must not contain pre-release or build tags.
    """
    v_str = v_str.strip()
    if not v_str:
        return None

    # Check for invalid characters in a partial version string
    if '-' in v_str or '+' in v_str:
        return None

    parts = v_str.split('.')

    # We allow up to 3 parts (M.m.p)
    if len(parts) > 3:
        return None

    try:
        major = int(parts[0]) if len(parts) >= 1 else 0
        minor = int(parts[1]) if len(parts) >= 2 else 0
        patch = int(parts[2]) if len(parts) >= 3 else 0
    except ValueError:
        return None

    # Check for leading zeros in non-zero parts
    if (len(parts[0]) > 1 and parts[0].startswith('0')) or \
       (len(parts[1]) > 1 and parts[1].startswith('0')) or \
       (len(parts[2]) > 1 and parts[2].startswith('0')):
        return None

    # Return the canonical representation (no pre/build)
    return Version(major, minor, patch, (), ())


def _evaluate_comparator(v_target: Version, spec_token: str) -> bool:
    """
    Evaluates a single comparator token against the target version.
    Spec_token can be '>=1.2.3', '^1.2.0', '1.2', etc.
    """
    token = spec_token.strip()
    if not token:
        return False

    # 1. Parse Prefix and Base Version
    op = ''
    base_str = token

    if token.startswith(('>=', '<=', '>', '<', '=')):
        # Determine operator length (1 or 2 chars)
        if token.startswith(('>=', '<=')):
            op = token[:2]
            base_str = token[2:].strip()
        else:
            op = token[0]
            base_str = token[1:].strip()
    elif token.startswith('^') or token.startswith('~'):
        op = token[0]
        base_str = token[1:].strip()
    else:
        # Bare version implies '='
        op = '='
        base_str = token

    # 2. Resolve base version (handling partial specifications)
    parsed_base = _parse_partial_version(base_str)
    if parsed_base is None:
        raise ValueError(f"Invalid or malformed version string in spec: {base_str}")

    # 3. Handle Tilde (~) and Caret (^) ranges
    if op == '~':
        base = parsed_base

        if base.prerelease:
             raise ValueError("Tilde operator (~) cannot be used with pre-release versions in spec.")

        # ~M.Y.Z implies >=M.Y.Z <M.(Y+1).0
        if base.major == 0 and base.minor == 0:
            # ^0.0.X -> >=0.0.X <0.0.(X+1)
            upper = Version(0, 0, base.patch + 1, (), ())
            lower = base
        elif base.major == 0:
            # ^0.Y.Z -> >=0.Y.Z <0.(Y+1).0
            upper = Version(0, base.minor + 1, 0, (), ())
            lower = base
        else:
            # ^M.Y.Z -> >=M.Y.Z <M.(Y+1).0
            upper = Version(base.major, base.minor + 1, 0, (), ())
            lower = base

        if v_target < lower: return False
        if v_target >= upper: return False
        return True

    elif op == '^':
        base = parsed_base

        # ^M.Y.Z implies >=M.Y.Z <(M+1).0.0 (unless M=0)
        if base.major > 0:
            # ^M.Y.Z -> >=M.Y.Z <(M+1).0.0
            lower = base
            upper = Version(base.major + 1, 0, 0, (), ())
        elif base.major == 0 and base.minor > 0:
            # ^0.Y.Z -> >=0.Y.Z <0.(Y+1).0
            lower = base
            upper = Version(0, base.minor + 1, 0, (), ())
        else: # base.major == 0 and base.minor == 0
            # ^0.0.Z -> >=0.0.Z <0.0.(Z+1)
            lower = base
            upper = Version(0, 0, base.patch + 1, (), ())

        if v_target < lower: return False
        if v_target >= upper: return False
        return True

    # 4. Handle Standard Comparators (>=, <=, >, <, =)
    else:
        # For standard operators, compare v_target against the resolved base version
        if op == '=':
            return v_target == parsed_base

        if op == '>':
            return v_target > parsed_base
        if op == '<':
            return v_target < parsed_base
        if op == '>=':
            return v_target >= parsed_base
        if op == '<=':
            return v_target <= parsed_base

        return False


def satisfies(version: Union[Version, str], spec: str) -> bool:
    """
    Checks if the given version satisfies all comparators in the specification.
    """
    if not spec or not spec.strip():
        raise ValueError("Specification string cannot be empty.")

    if isinstance(version, str):
        try:
            v_target = Version.parse(version)
        except ValueError as e:
            raise ValueError(f"Invalid version string provided: {e}")
    elif isinstance(version, Version):
        v_target = version
    else:
        raise TypeError("Version must be a Version object or a version string.")

    spec_tokens = spec.split()

    if not spec_tokens:
        raise ValueError("Specification must contain comparators.")

    for token in spec_tokens:
        try:
            if not _evaluate_comparator(v_target, token):
                return False
        except ValueError as e:
            # Re-raise parsing errors from comparator evaluation
            raise ValueError(f"Error evaluating comparator '{token}': {e}")

    return True
