# semver.py
import re
from functools import total_ordering
from typing import Tuple, Union, List, Iterable

# --- Internal Parsing Utilities ---

# Regex based on SemVer 2.0.0 specification
# MAJOR.MINOR.PATCH
VERSION_CORE_PATTERN = re.compile(r"^(?P<major>0|[1-9]\d*)\.(?P<minor>0|[1-9]\d*)\.(?P<patch>0|[1-9]\d*)$")

# Pre-release identifier: dot-separated identifiers of [0-9A-Za-z-]
PRERELEASE_IDENTIFIER_PATTERN = re.compile(r"^[0-9a-zA-Z-]+$")

# Full SemVer pattern: MAJOR.MINOR.PATCH-PRERELEASE+BUILD
SEMVER_PATTERN = re.compile(
    r"^(?P<major>0|[1-9]\d*)\."
    r"(?P<minor>0|[1-9]\d*)\."
    r"(?P<patch>0|[1-9]\d*)"
    r"(?:-(?P<prerelease>[0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?"
    r"(?:\+(?P<build>[0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$"
)

def parse_identifiers(identifier_str: str, is_prerelease: bool) -> Tuple[str, ...]:
    """Parses a dot-separated identifier string into a tuple of identifiers."""
    if not identifier_str:
        return tuple()

    identifiers = identifier_str.split('.')

    if is_prerelease:
        for identifier in identifiers:
            if not identifier:
                raise ValueError("Empty identifier in pre-release tag.")
            # Numeric identifiers must not have leading zeros
            if identifier.isdigit():
                if len(identifier) > 1 and identifier.startswith('0'):
                    raise ValueError(f"Numeric identifier '{identifier}' in pre-release tag cannot have leading zeros.")
            elif not PRERELEASE_IDENTIFIER_PATTERN.fullmatch(identifier):
                 raise ValueError(f"Invalid character in pre-release identifier: {identifier}")
    else: # Build metadata
        for identifier in identifiers:
            if not identifier:
                raise ValueError("Empty identifier in build metadata.")
            # Build identifiers can have leading zeros
            if not re.fullmatch(r"[0-9a-zA-Z-]+", identifier):
                 raise ValueError(f"Invalid character in build identifier: {identifier}")

    return tuple(identifiers)


# --- Comparison Logic ---

def _compare_versions(v1: "Version", v2: "Version") -> int:
    """
    Compares two fully parsed Version objects based on SemVer rules.
    Returns -1 if v1 < v2, 0 if v1 == v2, 1 if v1 > v2.
    """
    # 1. Compare core (Major, Minor, Patch)
    core1 = (v1.major, v1.minor, v1.patch)
    core2 = (v2.major, v2.minor, v2.patch)

    if core1 < core2: return -1
    if core1 > core2: return 1

    # Cores are equal, compare pre-release tags
    pr1 = v1.prerelease
    pr2 = v2.prerelease

    # If one has pre-release and the other doesn't, the pre-release is lower
    if pr1 and not pr2: return -1
    if not pr1 and pr2: return 1

    if not pr1 and not pr2:
        # Both stable, they are equal (build metadata is ignored)
        return 0

    # Both have pre-release tags: compare identifiers left-to-right
    for id1, id2 in zip(pr1, pr2):
        # Numeric comparison
        if id1.isdigit() and id2.isdigit():
            n1 = int(id1)
            n2 = int(id2)
            if n1 < n2: return -1
            if n1 > n2: return 1
        else:
            # String comparison (ASCII order)
            if id1 < id2: return -1
            if id1 > id2: return 1

    # If all common identifiers are equal, the shorter list is lower
    len1 = len(pr1)
    len2 = len(pr2)
    if len1 < len2: return -1
    if len1 > len2: return 1

    return 0


# --- Main Class Implementation ---

@total_ordering
class Version:
    """
    Represents a Semantic Version (MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]).
    """

    def __init__(self, major: int, minor: int, patch: int, prerelease: Tuple[str, ...], build: Tuple[str, ...]):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease
        self.build = build
        # Store original text to fulfill str() requirement precisely
        self._original_text = None 

    def _reconstruct_string(self) -> str:
        """Reconstructs the canonical string representation."""
        parts = [f"{self.major}.{self.minor}.{self.patch}"]

        if self.prerelease:
            pr_str = ".".join(self.prerelease)
            parts.append(f"-{pr_str}")

        if self.build:
            build_str = ".".join(self.build)
            parts.append(f"+{build_str}")

        return "".join(parts)

    @classmethod
    def parse(cls, text: str) -> 'Version':
        """
        Parses a full SemVer string into a Version object.
        Raises ValueError on any deviation from SemVer 2.0.0 rules.
        """
        if not text or text.strip() != text:
            raise ValueError("Version string cannot have surrounding whitespace.")
        if text.startswith('v'):
            raise ValueError("Version string cannot start with 'v'.")

        match = SEMVER_PATTERN.match(text)
        if not match:
            raise ValueError(f"Invalid SemVer format: {text}")

        groups = match.groupdict()

        major = int(groups['major'])
        minor = int(groups['minor'])
        patch = int(groups['patch'])

        prerelease_str = groups.get('prerelease')
        build_str = groups.get('build')

        prerelease = tuple()
        build = tuple()

        if prerelease_str:
            prerelease = parse_identifiers(prerelease_str, is_prerelease=True)

        if build_str:
            build = parse_identifiers(build_str, is_prerelease=False)

        # Instantiate, capturing the original text
        instance = cls(major, minor, patch, prerelease, build)
        instance._original_text = text
        return instance

    def __str__(self) -> str:
        """Returns the canonical text used during parsing."""
        if self._original_text is not None:
            return self._original_text
        return self._reconstruct_string()

    def __hash__(self) -> int:
        """Hash based on core version, ignoring build metadata."""
        return hash((self.major, self.minor, self.patch, self.prerelease))

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented

        # Equality ignores build metadata
        return (self.major == other.major and 
                self.minor == other.minor and 
                self.patch == other.patch and 
                self.prerelease == other.prerelease)

    def __lt__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return _compare_versions(self, other) < 0

    def __le__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return _compare_versions(self, other) <= 0

    def __gt__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return _compare_versions(self, other) > 0

    def __ge__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return _compare_versions(self, other) >= 0

    def bump(self, kind: str) -> 'Version':
        """
        Returns a new version bumped according to the specified kind.
        The result is always a clean, non-pre-release version.
        """
        kind = kind.lower()
        if kind == 'major':
            return Version(self.major + 1, 0, 0, (), ())
        elif kind == 'minor':
            return Version(self.major, self.minor + 1, 0, (), ())
        elif kind == 'patch':
            return Version(self.major, self.minor, self.patch + 1, (), ())
        else:
            raise ValueError(f"Invalid bump kind: {kind}. Must be 'major', 'minor', or 'patch'.")

# --- Range Checking Implementation ---

def _parse_partial_version(v_str: str) -> Version:
    """
