            return NotImplemented
        return _compare_versions(self, other) <= 0

    def __gt__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return _compare_versions(self, other) > 0

    def __ge__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return _compare_versions(self, other) >= 0

    def bump(self, kind: str) -> 'Version':
        """
        Returns a new version bumped according to the specified kind.
        The result is always a clean, non-pre-release version.
        """
        kind = kind.lower()
        if kind == 'major':
            return Version(self.major + 1, 0, 0, (), ())
        elif kind == 'minor':
            return Version(self.major, self.minor + 1, 0, (), ())
        elif kind == 'patch':
            return Version(self.major, self.minor, self.patch + 1, (), ())
        else:
            raise ValueError(f"Invalid bump kind: {kind}. Must be 'major', 'minor', or 'patch'.")

# --- Range Checking Implementation ---

def _parse_partial_version(v_str: str) -> Version:
    """
    Parses a partial version string (e.g., '1.2' or '1') into a full Version object 
    assuming patch=0 and no prerelease/build.
    """
    if '-' in v_str or '+' in v_str:
        raise ValueError("Partial version specification cannot include pre-release or build metadata.")

    parts = []
    try:
        # Ensure all parts are digits, as per partial version constraints
        for p in v_str.split('.'):
            if not p.isdigit():
                raise ValueError("Partial version components must be numeric.")
            parts.append(int(p))
    except ValueError:
        raise ValueError(f"Invalid numeric format in partial version: {v_str}")

    if not parts:
        raise ValueError(f"Invalid partial version: {v_str}")

    major = parts[0] if len(parts) >= 1 else 0
    minor = parts[1] if len(parts) >= 2 else 0
    patch = parts[2] if len(parts) >= 3 else 0

    # Partial versions are always treated as stable (no pre-release/build)
    return Version(major, minor, patch, (), ())


def satisfies(version: Union[Version, str], spec: str) -> bool:
    """
    Checks if a version satisfies a space-separated specification of comparators.
    """
    if not spec or not spec.strip():
        raise ValueError("Specification string cannot be empty.")

    spec_parts = spec.strip().split()

    # 1. Resolve target version
    if isinstance(version, str):
        try:
            v_target = Version.parse(version)
        except ValueError as e:
            raise ValueError(f"Invalid version string provided for comparison: {e}")
    elif isinstance(version, Version):
        v_target = version
    else:
        raise TypeError("Version must be a Version object or a string.")

    # 2. Check every comparator in the specification
    for comparator in spec_parts:
        op = None
        v_spec_str = comparator

        # Determine operator and extract version string
        if comparator.startswith('>='):
            op = '>='
            v_spec_str = comparator[2:]
        elif comparator.startswith('<='):
            op = '<='
            v_spec_str = comparator[2:]
        elif comparator.startswith('>'):
            op = '>'
            v_spec_str = comparator[1:]
        elif comparator.startswith('<'):
            op = '<'
            v_spec_str = comparator[1:]
        elif comparator.startswith('~'):
            op = '~'
            v_spec_str = comparator[1:]
        elif comparator.startswith('^'):
            op = '^'
            v_spec_str = comparator[1:]
        # Handle bare version V or explicit equality =V or ==V
        elif comparator.startswith(('=', '==')):
            op = '='
            v_spec_str = comparator[2:] if comparator.startswith('==') else comparator[1:]
        else:
            # Bare version means '='
            op = '='
            v_spec_str = comparator

        if not v_spec_str:
            raise ValueError(f"Missing version specifier for operator {op} in comparator '{comparator}'.")

        # Resolve the version specified in the comparator (V)
        try:
            v_spec = _parse_partial_version(v_spec_str)
        except ValueError as e:
            raise ValueError(f"Invalid version specification '{comparator}': {e}")

        is_satisfied = False

        # --- Apply Range Logic ---

        if op == '=':
            is_satisfied = (v_target == v_spec)

        elif op == '>=':
            is_satisfied = (v_target >= v_spec)

        elif op == '>':
            is_satisfied = (v_target > v_spec)

        elif op == '<=':
            is_satisfied = (v_target <= v_spec)

        elif op == '<':
            is_satisfied = (v_target < v_spec)

        elif op == '~':
            # Tilde (~): >= V AND < V_next_minor

            if v_target < v_spec:
                is_satisfied = False
            else:
                # Calculate upper bound: X.Y.Z -> Upper Bound is X.(Y+1).0
                if v_spec.minor == 0 and v_spec.major == 0:
                    # E.g., ~0.0.3 -> Upper Bound is 0.1.0
                    upper_bound = Version(0, v_spec.patch + 1, 0, (), ())
                elif v_spec.minor == 0:
                    # E.g., ~1.0.3 -> Upper Bound is 2.0.0
                    upper_bound = Version(v_spec.major + 1, 0, 0, (), ())
                else:
                    # E.g., ~1.2.3 -> Upper Bound is 1.3.0
                    upper_bound = Version(v_spec.major, v_spec.minor + 1, 0, (), ())

                is_satisfied = (v_target >= v_spec) and (v_target < upper_bound)

        elif op == '^':
            # Caret (^): >= V AND < V_next_major_or_minor

            if v_spec.major > 0:
                # Boundary is MAJOR + 1.0.0
                v_next = Version(v_spec.major + 1, 0, 0, (), ())
                is_satisfied = (v_target >= v_spec) and (v_target < v_next)
            elif v_spec.minor > 0:
                # Boundary is 0.(MINOR+1).0
                v_next = Version(0, v_spec.minor + 1, 0, (), ())
                is_satisfied = (v_target >= v_spec) and (v_target < v_next)
            else:
                # v_spec is 0.0.P. Boundary is 0.0.(P+1)
                v_next = Version(0, 0, v_spec.patch + 1, (), ())
                is_satisfied = (v_target >= v_spec) and (v_target < v_next)

        if not is_satisfied:
            return False

    return True
