from typing import List, Dict, Any, Callable, Union, Tuple

# --- Exceptions ---

class MachineError(Exception):
    """Base exception for FSM errors."""
    pass

class InvalidTransition(MachineError):
    """Raised when no transition matches the current state and event."""
    def __init__(self, state: str, event: str):
        self.state = state
        self.event = event
        super().__init__(f"Invalid transition: No transition found for event '{event}' in state '{state}'.")

class GuardRejected(MachineError):
    """Raised when transitions exist for the event but all guards reject."""
    def __init__(self, state: str, event: str):
        self.state = state
        self.event = event
        super().__init__(f"Transition rejected: All transitions for event '{event}' in state '{state}' failed their guards.")

# --- Data Classes ---

@dataclass
class State:
    name: str
    on_enter: Callable[['Machine', 'Event'], Any] = None
    on_exit: Callable[['Machine', 'Event'], Any] = None

@dataclass
class Transition:
    event: str
    source: Union[str, List[str], Tuple[str, ...]]
    target: Union[str, None]
    guard: Callable[['Machine', 'Event'], bool] = None
    action: Callable[['Machine', 'Event'], Any] = None

@dataclass
class Event:
    name: str
    source: str
    target: str
    data: Dict[str, Any]

# --- Main Machine Class ---

class Machine:
    def __init__(self, states: List[Union[str, State]], transitions: List[Transition], initial: str, context: Any = None):
        self._states_map: Dict[str, State] = {}
        self._state_names: List[str] = []
        self._transitions: List[Transition] = transitions
        self._initial_state: str = initial
        self._context: Any = context
        self._history: List[Tuple[str, str, str]] = []
        self._listeners: List[Callable[[str, Event, str], Any]] = []
        self._is_firing: bool = False

        self._validate_and_setup_states(states)

        # Initialize state
        self.state: str = initial

    def _validate_and_setup_states(self, states: List[Union[str, State]]):
        state_names = set()
        for item in states:
            if isinstance(item, State):
                name = item.name
                if name in state_names:
                    raise ValueError(f"Duplicate state name found: {name}")
                self._states_map[name] = item
                state_names.add(name)
            elif isinstance(item, str):
                name = item
                if name in state_names:
                    raise ValueError(f"Duplicate state name found: {name}")
                # Create anonymous state object if it's just a name string
                self._states_map[name] = State(name=name)
                state_names.add(name)
            else:
                raise TypeError("States must be State objects or strings.")

        if not self._states_map:
            raise ValueError("States list cannot be empty.")

        self._state_names = list(self._states_map.keys())

        if self._initial_state not in self._states_map:
            raise ValueError(f"Initial state '{self._initial_state}' is not a defined state.")

        # Validate transitions sources/targets
        for t in self._transitions:
            # Validate source
            if isinstance(t.source, str):
                if t.source not in self._states_map and t.source != '*':
                    raise ValueError(f"Transition source '{t.source}' is not a defined state.")
            elif isinstance(t.source, (list, tuple)):
                for src in t.source:
                    if src not in self._states_map and src != '*':
                        raise ValueError(f"Transition source '{src}' is not a defined state.")

            # Validate target
            if t.target is not None and t.target not in self._states_map:
                raise ValueError(f"Transition target '{t.target}' is not a defined state.")


    def fire(self, event_name: str, **data) -> str:
        if self._is_firing:
            raise MachineError("Cannot fire: Machine is already running a transition.")

        self._is_firing = True

        # 1. Find candidates
        candidates: List[Transition] = []
        for t in self._transitions:
            if t.event == event_name:
                is_source_match = False
                if t.source == '*':
                    is_source_match = True
                elif isinstance(t.source, str) and t.source == self.state:
                    is_source_match = True
                elif isinstance(t.source, (list, tuple)):
                    if self.state in t.source:
                        is_source_match = True

                if is_source_match:
                    candidates.append(t)

        if not candidates:
            self._is_firing = False
            raise InvalidTransition(self.state, event_name)

        # 2. Create the shared event data structure
        event = Event(name=event_name, source=self.state, target="", data=data)

        # 3. Evaluate guards
        chosen_transition: Union[Transition, None] = None
        for candidate in candidates:
            if candidate.guard is None:
                chosen_transition = candidate
                break

            try:
                guard_result = candidate.guard(self, event)
                if guard_result:
                    chosen_transition = candidate
                    break
            except MachineError:
                # If a guard raises an error, propagate it immediately
                self._is_firing = False
                raise

        if chosen_transition is None:
            self._is_firing = False
            raise GuardRejected(self.state, event_name)

        # --- Transition Execution ---

        current_state = self.state
        transition = chosen_transition
        new_state = transition.target

        # State Change Logic Setup
        state_changed = new_state != current_state

        try:
            # 4a. Run on_exit (only if state is changing, or if it's the same state but we need cleanup)
            # Per instructions: "A transition whose target is its own source still runs on_exit and on_enter."
            if current_state in self._states_map and self._states_map[current_state].on_exit:
                self._states_map[current_state].on_exit(self, event)

            # 4b. Run transition action
            if transition.action:
                transition.action(self, event)

            # 5. Handle internal vs external transitions
            if new_state is None:
                # Internal transition: state remains the same
                self._history.append((current_state, event_name, current_state))
                # Internal transitions run listeners but no on_enter/on_exit
                self._run_listeners(current_state, event, current_state)
                self.state = current_state
            else:
                # Normal transition: state changes
                self._history.append((current_state, event_name, new_state))
                self.state = new_state

                # 4c. Run on_enter for the new state
                if self.state in self._states_map and self._states_map[self.state].on_enter:
                    self._states_map[self.state].on_enter(self, event)

                # 4d. Run listeners
                self._run_listeners(current_state, event, new_state)

        except MachineError as e:
            # 6. Exception from Guard, on_exit, or Action -> State unchanged
            self._is_firing = False
            raise e
        except Exception as e:
            # 6. Exception from on_enter or Listener -> State has already changed
            self._is_firing = False
            raise e

        finally:
            self._is_firing = False
            return self.state

    def _run_listeners(self, source: str, event: Event, target: str):
        for listener in self._listeners:
            try:
                # Listeners are called with (source, event, target)
                listener(source, event, target)
            except Exception as e:
                # 6. Exception from Listener propagates unchanged
                raise e

    def can_fire(self, event_name: str, **data) -> bool:
        """Checks if a transition can fire without running any state/transition hooks."""

        # Create a temporary event object for guard evaluation
        event = Event(name=event_name, source=self.state, target="", data=data)

        candidates: List[Transition] = []
        for t in self._transitions:
            if t.event == event_name:
                is_source_match = False
                if t.source == '*':
                    is_source_match = True
                elif isinstance(t.source, str) and t.source == self.state:
                    is_source_match = True
                elif isinstance(t.source, (list, tuple)):
                    if self.state in t.source:
                        is_source_match = True

                if is_source_match:
                    candidates.append(t)

        if not candidates:
            return False

        # Check guards in order
        for candidate in candidates:
            if candidate.guard is None:
                return True

            try:
                if candidate.guard(self, event):
                    return True
            except Exception:
                # If guard raises, it implies a failure state, treat as rejection for can_fire context
                pass 

        return False


    def available_events(self) -> List[str]:
        """Returns sorted, de-duplicated event names possible from the current state."""
        events = set()
        for t in self._transitions:
            if t.source == '*' or (isinstance(t.source, str) and t.source == self.state) or (isinstance(t.source, (list, tuple)) and self.state in t.source):
                events.add(t.event)
        return sorted(list(events))

    def on_transition(self, listener: Callable[[str, Event, str], Any]):
        """Adds a listener hook."""
        self._listeners.append(listener)

    def reset(self):
        """Resets state to initial and clears history without running hooks."""
        self.state = self._initial_state
        self._history = []

    @property
    def history(self) -> List[Tuple[str, str, str]]:
        return list(self._history)

    def __repr__(self):
        return f"<Machine state='{self.state}'>"

