# --- Vending Machine Class ---

class VendingMachine:
    # Accepted coins in descending order for greedy change calculation
    COIN_DENOMINATIONS = [100, 25, 10, 5]

    def __init__(self, products: Dict[str, Tuple[int, int]]):
