from typing import Dict, Tuple, List, Any
from fsm import Machine, State, Transition, Event, InvalidTransition, GuardRejected

# --- Custom Exceptions ---

class VendingError(Exception):
    """Base exception for vending machine errors."""
    pass

class SoldOut(VendingError):
    """Raised when a requested product is out of stock."""
    pass

class InsufficientCredit(VendingError):
    """Raised when the inserted credit is less than the product price."""
    pass

# --- Vending Machine Class ---

class VendingMachine:
    # Accepted coins in descending order for greedy change calculation
    COIN_DENOMINATIONS = [100, 25, 10, 5]

    def __init__(self, products: Dict[str, Tuple[int, int]]):
        # products: {code: (price_cents, stock)}
        self.products: Dict[str, Tuple[int, int]] = products
        self._sales_log: Dict[str, int] = {}
        self._total_revenue: int = 0

        self._credit: int = 0
        self._state: str = 'idle'

        # --- FSM Setup ---

        # 1. Define States
        idle_state = State(name='idle')
        credit_state = State(name='credit')
        maintenance_state = State(name='maintenance')

        # 2. Define Transitions
        transitions = [
            # Idle -> Credit (Insert Coin)
            Transition(event='insert', source='idle', target='credit', guard=lambda m, e: True, action=lambda m, e: m._add_coin(e.data.get('coin'))),
            Transition(event='insert', source='credit', target='credit', guard=lambda m, e: True, action=lambda m, e: m._add_coin(e.data.get('coin'))),

            # Idle -> Maintenance (Service)
            Transition(event='service', source='idle', target='maintenance'),

            # Credit -> Idle (Cancel)
            Transition(event='cancel', source='credit', target='idle', action=lambda m, e: m._refund_credit(e.data)),

            # Credit -> Idle (Select Product)
            # The guard checks for code existence. The action handles stock/credit.
            Transition(event='select', source='credit', target='idle', guard=lambda m, e: m._can_select(e.data.get('code')), action=lambda m, e: m._process_sale(e.data.get('code'))),

            # Maintenance -> Idle (Resume)
            Transition(event='resume', source='maintenance', target='idle'),

            # Maintenance -> Maintenance (Restock - Internal Transition)
            Transition(event='restock', source='maintenance', target=None, action=lambda m, e: m._process_restock(e.data)),
        ]

        # 3. Initialize Machine
        self.machine = Machine(
            states=[idle_state, credit_state, maintenance_state],
            transitions=transitions,
            initial='idle',
            context=self # Pass self as context
        )

        # Initial state sync
        self._state = self.machine.state

    # --- Internal Helpers (Called by FSM actions) ---

    def _add_coin(self, coin: int):
        """Action hook for insert."""
        if coin not in {5, 10, 25, 100}:
            raise ValueError("Coin not accepted.")
        self._credit += coin

    def _refund_credit(self, event_data: Dict[str, Any]):
        """Action hook for cancel."""
        refund_coins = self._calculate_change(self._credit)
        self._credit = 0
        # In a real system, this would return the coins to the user.
        # We don't rely on this return value in the current FSM implementation.
        return refund_coins

    def _calculate_change(self, amount: int) -> List[int]:
        """Greedy change calculation."""
        change_coins: List[int] = []
        remaining = amount
        for coin in self.COIN_DENOMINATIONS:
            count = remaining // coin
            if count > 0:
                change_coins.extend([coin] * count)
                remaining -= count * coin
        return change_coins

    def _can_select(self, code: str) -> bool:
        """Guard hook for select: checks if code exists."""
        return code in self.products

    def _process_sale(self, code: str):
        """Action hook for select: performs sale, modifies credit."""
        price, stock = self.products[code]

        if stock <= 0:
            raise SoldOut() 

        # Transaction successful: Update stock, log sales, reduce credit.
        self.products[code] = (price, stock - 1)
        self._credit -= price
        self._total_revenue += price
        self._sales_log[code] = self._sales_log.get(code, 0) + 1

        # NOTE: The FSM transition target is 'idle'. The change calculation must be handled by the caller 
        # or the action must return change information (which it cannot easily do here). 
        # Since the credit is reduced by price, the required change is the original credit minus price.
        # This relies on the caller (select) knowing the original credit.

    def _process_restock(self, event_data: Dict[str, Any]):
        """Action hook for restock."""
        code = event_data['code']
        qty = event_data['qty']
        new_price = event_data.get('price')

        if qty < 1:
            raise ValueError("Restock quantity must be >= 1.")

        if code not in self.products:
            if new_price is None:
                raise KeyError(f"Price must be provided when adding a new code '{code}'.")

            # New product
            self.products[code] = (new_price, qty)
        else:
            # Existing product: update stock and potentially price
            current_price, current_stock = self.products[code]

            # Update price if provided
            if new_price is not None:
                self.products[code] = (new_price, current_stock + qty)
            else:
                # Update stock only
                self.products[code] = (current_price, current_stock + qty)


    # --- Public Interface ---

    @property
    def state(self) -> str:
        return self.machine.state

    @property
    def credit(self) -> int:
        return self._credit

    def stock(self, code: str) -> int:
        if code not in self.products:
            raise KeyError(f"Product code '{code}' not found.")
        return self.products[code][1]

    def price(self, code: str) -> int:
        if code not in self.products:
            raise KeyError(f"Product code '{code}' not found.")
        return self.products[code][0]

    @property
    def sales(self) -> Dict[str, int]:
        return self._sales_log

    @property
    def revenue(self) -> int:
        return self._total_revenue

    def insert(self, coin: int) -> int:
        """
        Adds coin, moves to credit state, returns new credit.
        Raises ValueError for invalid coin.
        """
        try:
            self.machine.fire('insert', coin=coin)
        except ValueError as e:
            # Coin validation failure, state remains unchanged because the action failed.
            raise e
        except InvalidTransition:
            # This only happens if we are not in 'idle' or 'credit'
            raise InvalidTransition(self.state, 'insert')

        return self.credit

    def select(self, code: str) -> List[int]:
        """Sells one unit, returns change, resets credit to 0, state to idle."""

        if self.state != 'credit':
            raise InvalidTransition(self.state, 'select')

        original_credit = self._credit

        try:
            # Fire transition. Guards/Actions handle SoldOut/InsufficientCredit.
            self.machine.fire('select', code=code)
        except KeyError:
            # Unknown code (Caught by guard/validation)
            raise KeyError(f"Product code '{code}' is unknown.")
        except SoldOut:
            # Stock check failed (Raised by action)
            raise SoldOut()
        except InsufficientCredit:
            # Credit check failed (Raised by guard/action if implemented)
            raise InsufficientCredit()
        except InvalidTransition:
            # Should be caught by initial check, but kept for robustness
            raise InvalidTransition(self.state, 'select')

        # Post-transaction: Calculate and return change.
        # The action successfully reduced self._credit by the price.
        # Change = Original Credit - Price. Since _process_sale only reduces credit by price, 
        # the change is the amount paid minus the price.

        try:
            price_paid = self.products[code][0]
        except KeyError:
            # Should be impossible if transition succeeded, but for safety
            raise VendingError("Product information corrupted after sale.")

        change_amount = original_credit - price_paid
        return self._calculate_change(change_amount)


    def cancel(self) -> List[int]:
        """Refunds the whole credit, state -> idle."""
        try:
            self.machine.fire('cancel', data={})
        except InvalidTransition as e:
            raise InvalidTransition(self.state, 'cancel')

        return self._calculate_change(self._credit)

    def service(self):
        """Enters maintenance state."""
        try:
            self.machine.fire('service')
        except InvalidTransition as e:
            raise InvalidTransition(self.state, 'service')

    def restock(self, code: str, qty: int, price: int = None):
        """Adds stock/updates price in maintenance mode."""
        if self.state != 'maintenance':
            raise InvalidTransition(self.state, 'restock')

        # Fire internal transition. The action hook handles input validation (qty >= 1, price presence).
        try:
            self.machine.fire('restock', code=code, qty=qty, price=price)
        except (ValueError, KeyError) as e:
            # If the action hook failed due to bad input data, treat it as an operational error
            # which for an internal transition should not change state.
            raise e 
        except InvalidTransition:
            # Should not happen if state check is correct
            raise InvalidTransition(self.state, 'restock')

    def resume(self):
        """Back to idle state."""
        try:
            self.machine.fire('resume')
        except InvalidTransition as e:
            raise InvalidTransition(self.state, 'resume')
