# fsm/machine.py
from dataclasses import dataclass, field
from typing import Any, List, Dict, Optional, Tuple, Union, Callable

# --- Exceptions ---

class MachineError(Exception):
    """Base class for FSM errors."""
    pass

class InvalidTransition(MachineError):
    """Raised when no transition matches the event from the current state."""
    def __init__(self, state: str, event: str):
        self.state = state
        self.event = event
        super().__init__(f"Invalid transition: No transition for event '{event}' found in state '{state}'.")

class GuardRejected(MachineError):
    """Raised when all matching transitions are rejected by their guards."""
    def __init__(self, state: str, event: str):
        self.state = state
        self.event = event
        super().__init__(f"Guard rejected: All transitions for event '{event}' from state '{state}' were rejected by guards.")

# --- Data Classes ---

@dataclass
class State:
    name: str
    on_enter: Optional[Callable[[Any, Any], None]] = None
    on_exit: Optional[Callable[[Any, Any], None]] = None

@dataclass
class Transition:
    event: str
    # Source can be state name, list/tuple of names, or '*'
    source: Union[str, List[str], Tuple[str, ...]]
    # Target can be state name or None for internal transition
    target: Optional[str]
    guard: Optional[Callable[[Any, Event], bool]] = None
    action: Optional[Callable[[Any, Event], None]] = None

@dataclass
class Event:
    name: str
    source: str
    target: str
    data: Dict[str, Any] = field(default_factory=dict)

# --- Machine Implementation ---

class Machine:
    """
    A Finite State Machine implementation.
    """
    def __init__(
        self,
        states: List[Union[str, State]],
        transitions: List[Transition],
        initial: str,
        context: Optional[Any] = None
    ):
        self.context = context
        self._states_map: Dict[str, Optional[State]] = {}
        self._state_names: List[str] = []
        self.transitions: List[Transition] = transitions
        self.history: List[Tuple[str, str, str]] = []
        self._listeners: List[Callable[[str, Event, str], None]] = []
        self._transition_context = False # Flag for recursive fire checking
        self._initial_state_name: str = initial

        self._validate_and_initialize_states(states)

        if initial not in self._states_map:
            raise ValueError(f"Initial state '{initial}' is not a defined state.")

        self.state: str = initial

        # Initialization hook run only for setup verification (no hooks run per requirement)
        self._initialize_states(states)

    def _validate_and_initialize_states(self, states: List[Union[str, State]]):
        state_names = set()
        self._states_map = {}

        for item in states:
            name = item.name if isinstance(item, State) else item
            if name in state_names:
                raise ValueError(f"Duplicate state name found: {name}")
            state_names.add(name)

            if isinstance(item, State):
                self._states_map[name] = item
            else:
                # Plain name state, store None in map
                self._states_map[name] = None

        self._state_names = sorted(list(state_names))

        # Validate all transitions reference existing states
        for t in self.transitions:
            sources = [t.source] if isinstance(t.source, str) else t.source

            for src in sources:
                if src == '*':
                    continue
                if src not in self._states_map:
                    raise ValueError(f"Transition references unknown source state '{src}'")

            target_name = t.target
            if target_name is not None and target_name not in self._states_map:
                raise ValueError(f"Transition references unknown target state '{target_name}'")

    def _initialize_states(self, states: List[Union[str, State]]):
        # Runs no hooks per requirement.
        pass

    def _resolve_source(self, source: Union[str, List[str], Tuple[str, ...]]) -> List[str]:
        """Resolves the source specification to a list of state names."""
        if isinstance(source, str):
            if source == '*':
                return self._state_names
            return [source]
        elif isinstance(source, (list, tuple)):
            return list(source)
        raise TypeError("Invalid source type for Transition.")

    def _find_candidates(self, event_name: str, current_state: str) -> List[Transition]:
        """Finds all transitions matching the event and current state, in order."""
        candidates = []
        for t in self.transitions:
            if t.event == event_name:
                sources = self._resolve_source(t.source)
                if current_state in sources:
                    candidates.append(t)
        return candidates

    def fire(self, event: str, **data) -> str:
        if self._transition_context:
            raise MachineError("Cannot fire while another fire operation is in progress.")

        self._transition_context = True
        original_state = self.state

        candidates = self._find_candidates(event, original_state)

        if not candidates:
            self._transition_context = False
            raise InvalidTransition(original_state, event)

        transition_to_take: Optional[Transition] = None

        # 3. Evaluate guards
        for t in candidates:
            is_guard_present = t.guard is not None

            try:
                # Create event object for guard hook
                event_obj = Event(t.event, original_state, t.target or original_state, data)

                if not is_guard_present or t.guard(self, event_obj):
                    transition_to_take = t
                    break
            except Exception as e:
                # If guard raises, it's treated as a rejection for the guard evaluation phase.
                # Per Rule 6, if it comes from a guard, state/history unchanged.
                self._transition_context = False
                raise e

        if transition_to_take is None:
            self._transition_context = False
            raise GuardRejected(original_state, event)

        # --- Transition Execution ---

        t = transition_to_take

        try:
            # 4. Run on_exit (if normal transition)
            if t.target is not None:
                current_state_obj = self._states_map[original_state]
                if current_state_obj and current_state_obj.on_exit:
                    event_obj_exit = Event(t.event, original_state, t.target, data)
                    current_state_obj.on_exit(self, event_obj_exit)

            # 5. Internal transition
            if t.target is None:
                if t.action:
                    event_obj_internal = Event(t.event, original_state, original_state, data)
                    t.action(self, event_obj_internal)
                self.history.append((original_state, t.event, original_state))
                return original_state # State unchanged

            # 4. Normal transition execution (target is a state name)

            # 4. Run transition action
            if t.action:
                event_obj_action = Event(t.event, original_state, t.target, data)
                t.action(self, event_obj_action)

            # State change and history logging
            self.state = t.target
            self.history.append((original_state, t.event, self.state))

            # 4. Run on_enter (on the new state)
            new_state_obj = self._states_map[self.state]
            if new_state_obj and new_state_obj.on_enter:
                event_obj_enter = Event(t.event, original_state, self.state, data)
                new_state_obj.on_enter(self, event_obj_enter)

            # 4. Run listeners
            event_obj_final = Event(t.event, original_state, self.state, data)
            for listener in self._listeners:
                listener(original_state, event_obj_final, self.state)

            return self.state

        except Exception as e:
            # 6. Exception handling: If any hook (action, on_enter, listener) throws, it propagates.
            # If it came from on_exit/guard, it should have been caught earlier or state/history unchanged.
            raise e
        finally:
            self._transition_context = False


    def can_fire(self, event: str, **data) -> bool:
        candidates = self._find_candidates(event, self.state)

        for t in candidates:
            if t.guard is None:
                return True
            try:
                event_obj = Event(t.event, self.state, t.target or self.state, data)
                if t.guard(self, event_obj):
                    return True
            except Exception:
                # Treat guard exception as rejection for can_fire check
                continue 

        return False

    def available_events(self) -> List[str]:
        """Returns the sorted, de-duplicated names of events from the current state."""
        available = set()
        for t in self.transitions:
            sources = self._resolve_source(t.source)
            if self.state in sources:
                available.add(t.event)
        return sorted(list(available))

    def on_transition(self, listener: Callable[[str, Event, str], None]):
        """Adds a listener callback."""
        self._listeners.append(listener)

    def reset(self):
        """Resets the state back to initial and clears history. Runs no hooks."""
        self.state = self._initial_state_name
        self.history.clear()


