# sheet/graph.py
from typing import Dict, Set, Iterable, List

class DependencyGraph:
    """
    Manages the dependency relationships between cells (precedents and dependents).
    All cell names must be in uppercase.
    """
    def __init__(self):
        # Maps cell_name -> set of cells it refers to (precedents)
        self._precedents: Dict[str, Set[str]] = {}
        # Maps cell_name -> set of cells that refer to it (dependents)
        self._dependents: Dict[str, Set[str]] = {}

    def set_dependencies(self, cell: str, precedents: Iterable[str]):
        """
        Replaces the precedents for a cell and updates the dependent map.
        """
        new_precedent_set = set(p for p in precedents if p)

        # 1. Clear old dependent links originating from 'cell'
        # We must clear links pointing *to* cell, but this structure tracks who *depends* on me.
        # We must update the dependents of the *old* precedents of 'cell' if we were tracking bidirectionally.
        # Here, we focus on updating who depends on 'cell'.

        # 2. Remove 'cell' from all previous dependents' lists (Cleanup phase)
        old_precedents = self._precedents.get(cell, set())
        for p in old_precedents:
            if cell in self._dependents.get(p, set()):
                self._dependents[p].remove(cell)

        # 3. Set new precedents and update dependents map
        self._precedents[cell] = new_precedent_set

        # Ensure the cell itself exists in the dependent map, even if it has no dependents yet
        if cell not in self._dependents:
            self._dependents[cell] = set()

        for p in new_precedent_set:
            if p not in self._dependents:
                self._dependents[p] = set()
            self._dependents[p].add(cell)

    def precedents(self, cell: str) -> Set[str]:
        """Returns the direct cells that 'cell' depends on."""
        return self._precedents.get(cell, set())

    def dependents(self, cell: str) -> Set[str]:
        """Returns the direct cells that depend on 'cell'."""
        return self._dependents.get(cell, set())

    def all_dependents(self, cell: str) -> Set[str]:
        """
        Returns every cell that refers to 'cell' directly or transitively.
        Includes 'cell' itself if it is part of a cycle.
        """
        queue = list(self.dependents.get(cell, set()))
        visited = set(self.dependents.get(cell, set()))
        all_deps = set(self.dependents.get(cell, set()))

        while queue:
            current = queue.pop(0)
            if current not in visited:
                visited.add(current)
                all_deps.add(current)

                for next_dep in self.dependents.get(current, set()):
                    if next_dep not in visited:
                        queue.append(next_dep)

        # Check for direct self-reference, which indicates a cycle involvement
        if cell in self.precedents.get(cell, set()):
             all_deps.add(cell)

        return all_deps

    def cycle_cells(self) -> Set[str]:
        """
        Returns every cell that lies on a cycle. Uses DFS.
        """
        visited: Set[str] = set()
        recursion_stack: Set[str] = set()
        cycle_nodes: Set[str] = set()

        # Collect all cells known to the graph (either as a cell or as a precedent/dependent)
        all_cells = set(self._precedents.keys())
        for preds in self._precedents.values():
            all_cells.update(preds)
        for deps in self._dependents.values():
            all_cells.update(deps)

        def dfs_cycle_check(node: str):
            if node in recursion_stack:
                # Cycle detected: this node is part of the cycle
                cycle_nodes.add(node)
                return True
            if node in visited:
                return False

            visited.add(node)
            recursion_stack.add(node)

            # Traverse PRECEDENTS (the direction of data flow that causes a cycle)
            for precedent in self._precedents.get(node, set()):
                if dfs_cycle_check(precedent):
                    # If the path through the precedent led to a cycle, this node is part of the path
                    cycle_nodes.add(node)

            recursion_stack.remove(node)
            return False

        for cell in all_cells:
            if cell not in visited:
                dfs_cycle_check(cell)

        return cycle_nodes
