from typing import Dict, Any, List, Set, Tuple, Union

from .formula import parse_formula, FormulaError, ErrorValue, evaluate, references
from .graph import DependencyGraph

# Define the maximum limits
MAX_COL = 26  # A-Z
MAX_ROW = 999

def _cell_name_to_coords(name: str) -> Tuple[str, int]:
    """Converts 'B7' to ('B', 7)"""
    name = name.upper()
    col_str = ""
    row_str = ""

    split_idx = 0
    while split_idx < len(name) and name[split_idx].isalpha():
        col_str += name[split_idx]
        split_idx += 1

    row_str = name[split_idx:]

    if not col_str or not row_str:
        raise ValueError(f"Invalid cell name format: {name}")

    try:
        row_num = int(row_str)
    except ValueError:
        raise ValueError(f"Invalid row number in cell name: {name}")

    if not (1 <= row_num <= MAX_ROW):
        raise ValueError(f"Row number {row_num} is out of bounds (1-999).")
    if len(col_str) > MAX_COL:
        raise ValueError(f"Column exceeds Z limit: {name}")

    # Check for leading zeros (e.g., A01 is invalid)
    if len(row_str) > 1 and row_str.startswith('0'):
        raise ValueError(f"Row number cannot have leading zeros: {name}")

    return col_str, row_num


class Sheet:
    """
    The main spreadsheet object managing cells, dependencies, and recalculation.
    """
    def __init__(self):
        # Stores raw input: {cell_name: raw_string}
        self._raw_inputs: Dict[str, str] = {} 
        # Stores calculated value: {cell_name: Value}
        self._values: Dict[str, Any] = {}
        # Dependency graph
        self._graph = DependencyGraph()
        self.evaluations: int = 0
        self._all_cells: Set[str] = set() # Set of all currently tracked cells

    def _ensure_valid_name(self, name: str):
        """Validates name format and range constraints."""
        try:
            # Use the internal helper which validates format and ranges
            _cell_name_to_coords(name)
        except ValueError as e:
            raise ValueError(str(e))

    def _recalculate_cell(self, name: str, cycle_cells: Set[str]) -> Any:
        """Calculates the value for a single cell based on dependencies."""
        raw_input = self._raw_inputs.get(name, "")

        if raw_input == "":
            self._values[name] = None
            return None

        # Rule 2: Cell on a cycle has the value #CYCLE! and is not evaluated.
        if name in cycle_cells:
            self._values[name] = ErrorValue("#CYCLE!")
            return ErrorValue("#CYCLE!")

        if raw_input.startswith('='):
            formula_source = raw_input[1:].strip()

            try:
                # 1. Parse
                ast = parse_formula(formula_source)

                # 2. Get dependencies
                deps = references(ast)

                # 3. Update graph state using the new precedents
                self._graph.set_dependencies(name, deps)

                # 4. Gather current values for lookups (must be up to date)
                lookup = {}
                for dep_name in deps:
                    # If a dependency itself is marked as a cycle, lookup returns ErrorValue("#CYCLE!")
                    lookup[dep_name] = self._values.get(dep_name)

                # 5. Evaluate
                new_value = evaluate(ast, lookup)

                # Rule 3 & 4: Update evaluation count only on successful formula evaluation
                if not isinstance(new_value, ErrorValue) or new_value != ErrorValue("#ERROR!"):
                    self.evaluations += 1

                self._values[name] = new_value
                return new_value

            except FormulaError as e:
                # Formula parsing failed, cell gets #ERROR!
                self._values[name] = ErrorValue("#ERROR!")
                return ErrorValue("#ERROR!")
            except Exception:
                # Catch unexpected runtime errors
                self._values[name] = ErrorValue("#ERROR!")
                return ErrorValue("#ERROR!")
        else:
            # Literal (number or text)
            try:
                if '.' in raw_input:
                    val = float(raw_input)
                else:
                    val = int(raw_input)
                self._values[name] = val
                return val
            except ValueError:
                # Text
                self._values[name] = raw_input
                return raw_input

    def set(self, name: str, raw: str) -> List[str]:
        """
        Sets the cell's input and triggers recalculations in dependency order.
        Returns the list of affected cells, sorted row-major.
        """
        self._ensure_valid_name(name)
        if not isinstance(raw, str):
            raise TypeError("Raw input must be a string.")

        # 1. Store the new raw input
        self._raw_inputs[name] = raw
        self._all_cells.add(name)

        # 2. Identify cycles based on current graph structure
        cycle_cells = self._graph.cycle_cells()

        # 3. Determine affected cells (self + all dependents)
        affected_cells = {name} | self._graph.all_dependents(name)

        # 4. Prepare ordered list of ALL tracked cells for traversal
        # Sorting key: (Row Number, Column Index) -> Row-major order
        def row_major_key(cell: str):
            col, row = _cell_name_to_coords(cell)
            col_idx = 0
            for char in col:
                col_idx += 1
            return (row, col_idx)

        all_tracked_sorted = sorted(list(self._all_cells), key=row_major_key)

        # 5. Recalculate only necessary cells in strict dependency order
        # We iterate over the globally sorted list, only processing those affected by the change.

        for cell_name in all_tracked_sorted:
            if cell_name not in affected_cells:
                continue

            current_value = self._values.get(cell_name)

            # Calculate and update value. The _recalculate_cell handles dependency checks,
            # cycle status, and updates self._values[cell_name].
            new_value = self._recalculate_cell(cell_name, cycle_cells)

            # Check if the value *actually* changed from its prior state
            # Note: If cell_name was None/uninitialized and is now being calculated, 
            # the change is considered valid, even if it moves from None to 0.
            if new_value != current_value:
                # The value was updated inside _recalculate_cell, but we track the change here.
                pass

        # Return the set of cells that were marked as affected, sorted row-major.
        return sorted(list(affected_cells), key=row_major_key)

    def get(self, name: str) -> Any:
        """Returns the cell's calculated value."""
        self._ensure_valid_name(name)
        return self._values.get(name)

    def raw(self, name: str) -> str:
        """Returns the last stored raw input."""
        self._ensure_valid_name(name)
        return self._raw_inputs.get(name, "")

    def cells(self) -> List[str]:
        """Returns all non-empty cells in row-major order."""
        def row_major_key(cell: str):
            col, row = _cell_name_to_coords(cell)
            col_idx = 0
            for char in col:
                col_idx += 1
            return (row, col_idx)

        return sorted([n for n in self._all_cells if self._raw_inputs[n] != ""], key=row_major_key)
