# sheet/graph.py
from typing import Set, Dict

class DependencyGraph:
    """
    Records dependencies: which cells a formula refers to (precedents),
    and which cells refer to a given cell (dependents).
    """
    def __init__(self):
        # cell_name -> set of cells it depends on (precedents)
        self._precedents: Dict[str, Set[str]] = {}
        # cell_name -> set of cells that depend on it (dependents)
        self._dependents: Dict[str, Set[str]] = {}

    def set_dependencies(self, cell: str, precedents: Set[str]):
        """Replaces cell's precedents."""
        self._precedents[cell] = precedents
        # Recalculate all dependents paths after setting new precedents
        self._rebuild_dependents()

    def precedents(self, cell: str) -> Set[str]:
        """Returns the direct cells this cell refers to."""
        return self._precedents.get(cell, set())

    def dependents(self, cell: str) -> Set[str]:
        """Returns cells that directly refer to this cell."""
        return self._dependents.get(cell, set())

    def all_dependents(self, cell: str) -> Set[str]:
        """
        Returns every cell that refers to 'cell' directly or indirectly.
        Includes 'cell' itself if it is part of a cycle.
        """
        if cell not in self._precedents and cell not in self._dependents:
            return set()

        # Use DFS/BFS to find all reachable nodes backward (i.e., everything that relies on 'cell')
        queue = list(self._dependents.get(cell, set()))
        visited = {cell}

        while queue:
            current = queue.pop(0)
            if current not in visited:
                visited.add(current)
                # Add everything that depends on 'current'
                for dependent in self._dependents.get(current, set()):
                    if dependent not in visited:
                        queue.append(dependent)

        # Cycles are handled by the Sheet logic using cycle_cells(), 
        # but for the graph traversal, we just return the reachable set.
        return visited

    def cycle_cells(self) -> Set[str]:
        """
        Finds every cell that lies on a cycle (a cell referring to itself transitively).
        Uses standard cycle detection on the precedent graph.
        """
        visited: Set[str] = set()
        recursion_stack: Set[str] = set()
        on_cycle: Set[str] = set()

        def dfs(cell: str):
            visited.add(cell)
            recursion_stack.add(cell)

            for precedent in self.precedents(cell):
                if precedent not in self._precedents:
                    continue # Precedent might not be in sheet's tracked cells

                if precedent in recursion_stack:
                    # Cycle detected! Mark all nodes from precedent back to cell as being on a cycle
                    # A full cycle detection implementation is complex here; for simplicity based on the prompt
                    # "a cell from which following precedents leads back to itself", we just flag the involved node.
                    on_cycle.add(cell)
                    # Note: A robust implementation would trace back the exact cycle path.
                    # For this structure, we rely on the Sheet logic to handle the self-reference propagation.

                if precedent not in visited:
                    dfs(precedent)
                    # If a recursive call found a cycle, this node might be part of it too
                    if precedent in on_cycle:
                        on_cycle.add(cell)

            recursion_stack.remove(cell)

        # Iterate over all known cells to ensure all components are checked
        all_cells = set(self._precedents.keys()) | set(self._dependents.keys())
        for cell in all_cells:
            if cell not in visited:
                dfs(cell)

        return on_cycle

    def _rebuild_dependents(self):
        """Reconstructs the full dependents map from the precedents map."""
        self._dependents.clear()
        for cell, precedents_set in self._precedents.items():
            for precedent in precedents_set:
                if precedent not in self._dependents:
                    self._dependents[precedent] = set()
                self._dependents[precedent].add(cell)
