# sheet/sheet.py
from typing import Dict, Any, Set, Optional, List
from .formula import (
    parse_formula, FormulaError, ErrorValue, ERROR_GENERAL, ERROR_CYCLE, 
    references, evaluate
)
from .graph import DependencyGraph

# Constants
MAX_COLUMNS = 26  # A-Z
MAX_ROWS = 999

class Sheet:
    def __init__(self):
        # Stores raw input: name -> raw_string
        self._raw_values: Dict[str, str] = {}
        # Stores computed values: name -> actual_value (int, float, str, None, ErrorValue)
        self._values: Dict[str, Any] = {}
        # Tracks dependencies
        self.graph = DependencyGraph()
        # Tracks evaluation count
        self.evaluations: int = 0

    def _validate_name(self, name: str) -> str:
        """Validates and uppercases a cell name."""
        name = name.upper()

        if not name:
            raise ValueError("Cell name cannot be empty.")

        # Check format: Letter(s) followed by digits
        col_part = "".join(filter(str.isalpha, name))
        row_part = "".join(filter(str.isdigit, name))

        if not col_part or not row_part:
            raise ValueError(f"Invalid cell name format: {name}")

        if len(col_part) > MAX_COLUMNS:
            raise ValueError(f"Column exceeds Z: {name}")

        try:
            row = int(row_part)
            if not (1 <= row <= MAX_ROWS):
                 raise ValueError
        except ValueError:
            raise ValueError(f"Row out of range (1-{MAX_ROWS}): {name}")

        # Row cannot have leading zeros unless it is exactly '0', which is disallowed by range check
        if len(row_part) > 1 and row_part.startswith('0'):
             raise ValueError(f"Row cannot have leading zeros: {name}")

        return name

    def _get_cell_value(self, name: str) -> Any:
        """Retrieves the current value from the internal state."""
        if name not in self._values:
            # Should only happen if called before initialization/update, treat as empty
            return None
        return self._values[name]

    def _is_cell_on_cycle(self, name: str) -> bool:
        """Checks if a cell is marked as being on a cycle by the graph."""
        return name in self.graph.cycle_cells()

    def _recalculate_cell(self, name: str) -> tuple[Any, bool]:
        """
        Calculates the value for a single cell, respecting cycles.
        Returns (new_value, was_changed)
        """
        if self._is_cell_on_cycle(name):
            return ERROR_CYCLE, False

        raw_input = self._raw_values.get(name)

        # 1. Empty cell
        if raw_input == '':
            current_value = None
            return current_value, self._values.get(name) != None

        # 2. Formula cell
        if raw_input.startswith('='):
            formula_source = raw_input[1:].strip()
            try:
                tree = parse_formula(formula_source)

                # Gather dependencies first (to ensure all prerequisites are updated)
                deps = references(tree)

                # Check for cycles based on formula dependencies *before* evaluation
                for dep_name in deps:
                    if self._is_cell_on_cycle(dep_name):
                        # If any dependency is on a cycle, this cell also gets the cycle error
                        return ERROR_CYCLE, False

                # Evaluate using the current state of the sheet
                new_value = evaluate(tree, self._get_cell_value)

                # Handle formula result being a string (text return) vs numeric/error
                if isinstance(new_value, str) and new_value not in (ERROR_GENERAL, ERROR_CYCLE):
                    # Rule 2: Formula only containing a reference results in text unchanged
                    pass
                elif isinstance(new_value, ErrorValue):
                    # Propagate errors (Rule 3)
                    pass

                return new_value, self._values.get(name) != new_value

            except FormulaError as e:
                # Parsing error results in general error
                return ERROR_GENERAL, self._values.get(name) != ERROR_GENERAL
            except Exception:
                # Catch unexpected evaluation errors
                return ERROR_GENERAL, self._values.get(name) != ERROR_GENERAL

        # 3. Numeric input (simple string to number)
        try:
            if '.' in raw_input:
                new_value = float(raw_input)
            else:
                new_value = int(raw_input)

            was_changed = self._values.get(name) != new_value
            return new_value, was_changed

        except ValueError:
            # 4. Text input (must be stored exactly as given)
            new_value = raw_input
            was_changed = self._values.get(name) != new_value
            return new_value, was_changed


    def set(self, name: str, raw: str) -> List[str]:
        """
        Sets the raw input for a cell and recalculates dependent values.
        Returns cells whose values may have changed, in row-major order.
        """
        validated_name = self._validate_name(name)
        if validated_name != name.upper(): # Ensure case normalization happened if input was mixed case
             name = validated_name

        if not isinstance(raw, str):
            raise TypeError("Raw input must be a string.")

        # Store the new raw value
        old_raw = self._raw_values.get(name, '')
        self._raw_values[name] = raw

        # 1. Determine which cells need recalculation (the cell itself and all dependents)
        dependent_cells = self.graph.all_dependents(name) | {name}

        # 2. Recalculate all potentially affected cells
        changed_cells_map: Dict[str, Any] = {} # {name: new_value}
        recalc_queue = list(dependent_cells)

        # Iteratively recalculate until a full pass results in no changes
        # This loop ensures that dependencies are updated before dependents are evaluated (topological sort simulation)

        made_a_change_in_pass = True
        while made_a_change_in_pass:
            made_a_change_in_pass = False

            # Sort the queue to respect row-major order for output, but the evaluation order matters most.
            # We iterate over the current set of candidates.
            candidates = sorted(list(set(recalc_queue)), key=lambda n: (int(n[1:]), n[0])) 

            for current_name in candidates:
                if current_name in changed_cells_map:
                    continue # Already calculated in this pass

                old_value = self._values.get(current_name)

                # Recalculate and get change status
                new_value, was_changed = self._recalculate_cell(current_name)

                self._values[current_name] = new_value
                changed_cells_map[current_name] = new_value

                if was_changed:
                    made_a_change_in_pass = True

                    # If this cell changed, all its dependents must be re-queued
                    for dependent in self.graph.dependents(current_name):
                        if dependent not in changed_cells_map:
                            recalc_queue.append(dependent)

        # 3. Update evaluation count based on formula cells that were actually recalculated
        count_increase = 0
        for name in dependent_cells:
            if self._raw_values.get(name, '').startswith('=') and name in changed_cells_map:
                # We assume _recalculate_cell correctly determined if a formula cell was evaluated
                # If the value changed AND it's a formula, it was evaluated.
                # A more precise implementation would track if evaluation *ran*, not just if the *value* changed.
                # Following Rule 3 strictly: "evaluates each formula cell in its returned list that is not on a cycle exactly once"

                # We must ensure we only count unique formula cells in the affected set
                if self._raw_values.get(name, '').startswith('='):
                    # A heuristic: if the value changed, and it's a formula, we count it.
                    # This assumes the evaluation run was successful and counted.
                    pass 

        # Reset and recount to strictly adhere to Rule 3: 
        # "evaluates each formula cell in its returned list that is not on a cycle exactly once"
        # This implies we only count the unique formula cells in the initial dependent_cells set 
        # that were not on a cycle AND whose calculation ran.

        formula_cells_evaluated_this_set = set()
        for name in dependent_cells:
            if self._raw_values.get(name, '').startswith('=') and not self._is_cell_on_cycle(name):
                # Since the iterative loop ran, and the cell is not a cycle, it was evaluated once per trigger event.
                # To satisfy "exactly once" per set() call, we check if the value *is* a formula output.
                formula_cells_evaluated_this_set.add(name)

        self.evaluations += len(formula_cells_evaluated_this_set)


        # 4. Return results in row-major order
        result_list = []
        all_relevant_names = sorted(list(changed_cells_map.keys()), key=lambda n: (int(n[1:]), n[0]))

        for name in all_relevant_names:
            result_list.append(name)

        return result_list

    def get(self, name: str) -> Any:
        """Returns the calculated value of the cell."""
        validated_name = self._validate_name(name)
        return self._values.get(validated_name)

    def raw(self, name: str) -> str:
        """Returns the input string stored for the cell."""
        validated_name = self._validate_name(name)
        return self._raw_values.get(validated_name, '')

    def cells(self) -> List[str]:
        """Returns all non-empty cells in row-major order."""
        all_names = list(self._raw_values.keys())

        # Filter out empty raw values ('')
        non_empty_names = [n for n in all_names if self._raw_values[n] != '']

        # Sort by row (numeric part) then column (alphabetic part)
        def sort_key(name):
            row = int(name[1:])
            col = name[0]
            return (row, col)

        return sorted(non_empty_names, key=sort_key)
