# sheet/formula.py
from typing import Union, List, Any, Set
import re

# --- Error Values ---

class ErrorValue(str):
    """A string subclass used to represent calculated errors."""
    pass

ERROR_GENERAL = ErrorValue("#ERROR!")
ERROR_CYCLE = ErrorValue("#CYCLE!")

# --- AST Nodes ---

class ASTNode:
    """Base class for Abstract Syntax Tree nodes."""
    pass

class NumberNode(ASTNode):
    def __init__(self, value: Union[int, float]):
        self.value = value

class RefNode(ASTNode):
    def __init__(self, name: str):
        self.name = name

class BinaryOpNode(ASTNode):
    def __init__(self, left: ASTNode, op: str, right: ASTNode):
        self.left = left
        self.op = op  # '+', '-', '*', '/'
        self.right = right

class UnaryOpNode(ASTNode):
    def __init__(self, op: str, operand: ASTNode):
        self.op = op  # '+', '-'
        self.operand = operand

# --- Formula Parsing and Evaluation ---

def references(tree: ASTNode) -> Set[str]:
    """Recursively finds all cell references in the AST."""
    refs = set()
    if isinstance(tree, NumberNode):
        return refs
    elif isinstance(tree, RefNode):
        return {tree.name}
    elif isinstance(tree, BinaryOpNode):
        refs.update(references(tree.left))
        refs.update(references(tree.right))
        return refs
    elif isinstance(tree, UnaryOpNode):
        return references(tree.operand)
    else:
        raise TypeError(f"Unknown AST node type: {type(tree)}")

def evaluate(tree: ASTNode, lookup: callable) -> Union[int, float, str, ErrorValue]:
    """
    Evaluates the AST tree using the provided lookup function for cell values.

    lookup(name) -> value (int, float, str, None, ErrorValue)
    """

    def _handle_error(left_val, right_val):
        """Handles propagation of errors during binary operations."""
        if isinstance(left_val, ErrorValue):
            return left_val
        if isinstance(right_val, ErrorValue):
            return right_val
        return ERROR_GENERAL

    def _apply_binary(left_val, op, right_val):
        """Applies the binary operation based on types."""

        # Check for error propagation first
        if isinstance(left_val, ErrorValue) or isinstance(right_val, ErrorValue):
            return _handle_error(left_val, right_val)

        # Handle text interaction (Rule 3)
        if isinstance(left_val, str) or isinstance(right_val, str):
            return ERROR_GENERAL

        # Numeric operations
        if op == '+':
            return left_val + right_val
        elif op == '-':
            return left_val - right_val
        elif op == '*':
            return left_val * right_val
        elif op == '/':
            if right_val == 0:
                return ERROR_GENERAL
            return left_val / right_val

        return ERROR_GENERAL

    def _apply_unary(op, operand_val):
        """Applies unary operations."""
        if isinstance(operand_val, ErrorValue):
            return operand_val
        if isinstance(operand_val, str):
            return ERROR_GENERAL # Unary op on text results in error

        if op == '+':
            return operand_val
        elif op == '-':
            # Convert to number if it's an int, otherwise float
            try:
                return -float(operand_val) if isinstance(operand_val, int) else -operand_val
            except TypeError:
                 # Should only happen if operand_val was None or unexpected, treat as error
                 return ERROR_GENERAL


    if isinstance(tree, NumberNode):
        return tree.value

    elif isinstance(tree, RefNode):
        name = tree.name
        value = lookup(name)

        # Rule 2: Empty cell (None) gives 0. Text reference returns text.
        if value is None:
            return 0
        if isinstance(value, str):
            return value

        # Return the underlying numeric/error value
        return value

    elif isinstance(tree, BinaryOpNode):
        left_val = evaluate(tree.left, lookup)
        right_val = evaluate(tree.right, lookup)
        return _apply_binary(left_val, tree.op, right_val)

    elif isinstance(tree, UnaryOpNode):
        operand_val = evaluate(tree.operand, lookup)
        return _apply_unary(tree.op, operand_val)

    else:
        return ERROR_GENERAL

# --- Parser Implementation ---

class Token:
    """Simple token structure."""
    def __init__(self, type: str, value: Any = None):
        self.type = type
        self.value = value

# Regex definitions
WHITESPACE = re.compile(r'\s+')
# Match number, allowing leading sign only if it's not already consumed by context (handled later)
NUMBER_PATTERN = re.compile(r'\d+(\.\d*)?')
LETTER_PATTERN = re.compile(r'[a-zA-Z]')

def is_valid_ref_row(row_str: str) -> bool:
    """Validates row string against constraints (1-999, no leading zeros)."""
    if not row_str:
        return False

    try:
        row = int(row_str)
        if not (1 <= row <= 999):
            return False
        # Leading zero check: only valid if the string is "0" (which is disallowed by range) or has no leading zero.
        if len(row_str) > 1 and row_str.startswith('0'):
            return False
        return True
    except ValueError:
        return False

def tokenize(source: str) -> List[Token]:
    tokens = []
    i = 0
    while i < len(source):
        match_ws = WHITESPACE.match(source, i)
        if match_ws:
            i = match_ws.end()
            continue

        char = source[i]
        if char in '+-*/()':
            tokens.append(Token(char, char))
            i += 1
            continue

        # Check for reference (letters followed by digits)
        match_letters = LETTER_PATTERN.match(source, i)
        if match_letters:
            start_letters = i
            i = match_letters.end()

            start_digits = i
            # Consume subsequent digits
            while i < len(source) and source[i].isdigit():
                i += 1

            ref_str = source[start_letters:i]

            # Validate the reference structure immediately
            col_part = ref_str[:len(ref_str) - (i - start_digits)] # Columns are the initial letters
            row_part = ref_str[len(ref_str) - (i - start_digits):] # Rows are the digits

            if len(col_part) == 0 or not is_valid_ref_row(row_part):
                 raise FormulaError(f"Invalid reference format or value: {ref_str}")

            tokens.append(Token('REF', ref_str))
            continue

        # Check for number (must not be starting a reference)
        match_num = NUMBER_PATTERN.match(source, i)
        if match_num and not LETTER_PATTERN.match(source, i):
            value_str = match_num.group(0)
            tokens.append(Token('NUMBER', value_str))
            i = match_num.end()
            continue

        raise FormulaError(f"Illegal character or sequence at position {i}: {source[i:]}")

    tokens.append(Token('EOF'))
    return tokens


class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token:
        return self.tokens[self.pos]

    def consume(self, expected_type: str = None, expected_value: str = None) -> Token:
        token = self.peek()
        if expected_type and token.type != expected_type:
            raise FormulaError(f"Expected token type {expected_type}, got {token.type} ('{token.value}')")
        if expected_value and token.value != expected_value:
            raise FormulaError(f"Expected token value {expected_value}, got {token.value}")
        self.pos += 1
        return token

    # Grammar implementation:
    # expr   := term {(+ | -) term}
    # term   := unary {(* | /) unary}
    # unary  := (+ | -) unary | number | ref | ( expr )
    # number := digits [. digits]
    # ref    := letters digits

    def parse_number(self) -> NumberNode:
        token = self.consume('NUMBER')
        value_str = token.value
        try:
            if '.' in value_str:
                return NumberNode(float(value_str))
            else:
                return NumberNode(int(value_str))
        except ValueError:
            raise FormulaError(f"Invalid number format: {value_str}")

    def parse_reference(self) -> RefNode:
        token = self.consume('REF')
        return RefNode(token.value.upper())

    def parse_primary(self) -> ASTNode:
        token = self.peek()

        if token.type == 'NUMBER':
            self.consume('NUMBER')
            return self.parse_number()

        elif token.type == 'REF':
            self.consume('REF')
            return self.parse_reference()

        elif token.type == '(':
            self.consume('(')
            node = self.parse_expr()
            self.consume(')')
            return node

        # Unary operators are handled in parse_unary, but they might look like a primary start
        # We rely on parse_unary to catch these.
        else:
            raise FormulaError(f"Unexpected token in primary expression: {token}")

    def parse_term(self) -> ASTNode:
        # term := unary {(* | /) unary}
        node = self.parse_unary()

        while self.peek().type in ('*', '/'):
            op_token = self.consume()
            right = self.parse_unary()
            node = BinaryOpNode(node, op_token.value, right)
        return node

    def parse_unary(self) -> ASTNode:
        # unary := (+ | -) unary | number | ref | ( expr )
        token = self.peek()
        if token.type in ('+', '-'):
            op = self.consume(token.type).value
            # Recursive call to unary to handle chained unary operators like --5
            operand = self.parse_unary() 
            return UnaryOpNode(op, operand)
        return self.parse_primary()

    def parse_expr(self) -> ASTNode:
        # expr := term {(+ | -) term}
        node = self.parse_term()

        while self.peek().type in ('+', '-'):
            op_token = self.consume()
            right = self.parse_term()
            node = BinaryOpNode(node, op_token.value, right)
        return node

def parse_formula(source: str) -> ASTNode:
    """
    Parses the formula text (after '=') into an AST.
    Raises FormulaError on failure.
    """
    if not source.strip():
        raise FormulaError("Formula source cannot be empty.")

    # 1. Tokenize
    tokens = tokenize(source)

    # 2. Parse
    parser = Parser(tokens)
    tree = parser.parse_expr()

    # 3. Check for remaining tokens (incomplete expression)
    if parser.peek().type != 'EOF':
        raise FormulaError("Incomplete or unexpected tokens remaining after parsing.")

    return tree
