# sheet/sheet.py
from typing import Dict, Any, Set, Optional, List, Tuple
from .formula import (
    parse_formula, FormulaError, ErrorValue, ERROR_GENERAL, ERROR_CYCLE, 
    references, evaluate
)
from .graph import DependencyGraph

# Constants
MAX_COLUMNS = 26  # A-Z
MAX_ROWS = 999

class Sheet:
    def __init__(self):
        self._raw_values: Dict[str, str] = {}
        self._values: Dict[str, Any] = {}
        self.graph = DependencyGraph()
        self.evaluations: int = 0

    def _validate_name(self, name: str) -> str:
        """Validates and uppercases a cell name."""
        name = name.upper()

        if not name:
            raise ValueError("Cell name cannot be empty.")

        # Extract columns (letters) and rows (digits)
        col_part = "".join(filter(str.isalpha, name))
        row_part = "".join(filter(str.isdigit, name))

        if not col_part or not row_part:
            raise ValueError(f"Invalid cell name format: {name}")

        if len(col_part) > MAX_COLUMNS:
            raise ValueError(f"Column exceeds Z: {name}")

        try:
            row = int(row_part)
            if not (1 <= row <= MAX_ROWS):
                 raise ValueError
        except ValueError:
            raise ValueError(f"Row out of range (1-{MAX_ROWS}): {name}")

        # Row cannot have leading zeros unless it is exactly '0', which is disallowed by range check
        if len(row_part) > 1 and row_part.startswith('0'):
             raise ValueError(f"Row cannot have leading zeros: {name}")

        return name

    def _get_cell_value(self, name: str) -> Any:
        """Retrieves the current value from the internal state."""
        return self._values.get(name)

    def _is_cell_on_cycle(self, name: str) -> bool:
        """Checks if a cell is marked as being on a cycle by the graph."""
        return name in self.graph.cycle_cells()

    def _recalculate_cell(self, name: str, trigger_source: str) -> Tuple[Any, bool, bool]:
        """
        Calculates the value for a single cell.
        Returns (new_value, was_changed, was_evaluated_formula)
        """
        is_formula = self._raw_values.get(name, '').startswith('=')

        if self._is_cell_on_cycle(name):
            return ERROR_CYCLE, False, False

        raw_input = self._raw_values.get(name)

        # 1. Empty cell
        if raw_input == '':
            return None, self._values.get(name) != None, False

        # 2. Formula cell
        if is_formula:
            formula_source = raw_input[1:].strip()
            was_evaluated_formula = False

            try:
                tree = parse_formula(formula_source)
                deps = references(tree)

                # Check for cycles based on formula dependencies
                for dep_name in deps:
                    if self._is_cell_on_cycle(dep_name):
                        return ERROR_CYCLE, False, True

                # Evaluate
                new_value = evaluate(tree, self._get_cell_value)
                was_evaluated_formula = True

                return new_value, self._values.get(name) != new_value, was_evaluated_formula

            except FormulaError:
                # Parsing error results in general error
                return ERROR_GENERAL, self._values.get(name) != ERROR_GENERAL, True
            except Exception:
                # Catch unexpected evaluation errors
                return ERROR_GENERAL, self._values.get(name) != ERROR_GENERAL, True

        # 3. Numeric input
        try:
            if '.' in raw_input:
                new_value = float(raw_input)
            else:
                new_value = int(raw_input)
            return new_value, self._values.get(name) != new_value, False

        except ValueError:
            # 4. Text input
            new_value = raw_input
            return new_value, self._values.get(name) != new_value, False


    def set(self, name: str, raw: str) -> List[str]:
        """
        Sets the raw input for a cell and recalculates dependent values.
        Returns cells whose value may have changed, in row-major order.
        """
        validated_name = self._validate_name(name)

        old_raw = self._raw_values.get(validated_name, '')
        self._raw_values[validated_name] = raw

        # 1. Determine the set of cells that need evaluation (self + all dependents)
        dependent_cells = self.graph.all_dependents(validated_name) | {validated_name}

        # --- Iterative Calculation (Simulating dependency resolution) ---

        changed_cells: Dict[str, Any] = {} # {name: new_value}

        # Queue holds cells whose value might change or whose dependencies just changed.
        recalc_queue = list(dependent_cells)

        # Keep track of which cells we have successfully evaluated in this set() call
        formula_cells_evaluated_this_set: Set[str] = set()

        # We use a set to manage the candidates to process in each pass to avoid infinite loops in complex cases
        candidates_to_process = set(dependent_cells)

        while candidates_to_process:
            next_candidates = set()

            # Sort candidates to ensure deterministic behavior (though evaluation order matters more)
            current_list = sorted(list(candidates_to_process), key=lambda n: (int(n[1:]), n[0]))
            candidates_to_process.clear()

            for current_name in current_list:
                if current_name in changed_cells:
                    continue

                # Calculate value
                new_value, was_changed, was_evaluated = self._recalculate_cell(
                    current_name, validated_name
                )

                # Update state
                self._values[current_name] = new_value
                changed_cells[current_name] = new_value

                if was_changed:
                    # If the value changed, all its dependents must be re-queued for the next pass
                    for dependent in self.graph.dependents(current_name):
                        if dependent in dependent_cells and dependent not in changed_cells:
                            next_candidates.add(dependent)

                if was_evaluated:
                    formula_cells_evaluated_this_set.add(current_name)


            if next_candidates:
                candidates_to_process = next_candidates
            else:
                # If no changes occurred in this pass, but candidates remain (e.g., due to initial structure), we stop.
                break


        # 3. Update evaluation count (Rule 3)
        self.evaluations += len(formula_cells_evaluated_this_set)


        # 4. Return results in row-major order
        result_list = []
        all_relevant_names = sorted(list(changed_cells.keys()), key=lambda n: (int(n[1:]), n[0]))

        for name in all_relevant_names:
            result_list.append(name)

        return result_list

    def get(self, name: str) -> Any:
        """Returns the calculated value of the cell."""
        validated_name = self._validate_name(name)
        return self._values.get(validated_name)

    def raw(self, name: str) -> str:
        """Returns the input string stored for the cell."""
        validated_name = self._validate_name(name)
        return self._raw_values.get(validated_name, '')

    def cells(self) -> List[str]:
        """Returns all non-empty cells in row-major order."""
        all_names = list(self._raw_values.keys())

        non_empty_names = [n for n in all_names if self._raw_values[n] != '']

        def sort_key(name):
            # Assumes valid name format due to filtering by self._raw_values keys
            row = int(name[1:])
            col = name[0]
            return (row, col)

        return sorted(non_empty_names, key=sort_key)
