        # 2. Cycle Check (Rule 2)
        if self._is_cell_on_cycle(name):
            return ERROR_CYCLE, self._values.get(name) != ERROR_CYCLE, False

        # 3. Formula cell
        if is_formula:
            formula_source = raw_input[1:].strip()
            try:
                tree = parse_formula(formula_source)

                # Evaluation handles cycle propagation through lookup, so we just evaluate.
                # If the lookup encounters a cycle, evaluation returns ERROR_CYCLE.
                new_value = evaluate(tree, self._get_cell_value)

                # Did the value change?
                was_changed = self._values.get(name) != new_value

                return new_value, was_changed, True

            except FormulaError:
                # Parsing error results in general error
                was_changed = self._values.get(name) != ERROR_GENERAL
                return ERROR_GENERAL, was_changed, True
            except Exception:
                # Catch unexpected evaluation errors
                was_changed = self._values.get(name) != ERROR_GENERAL
                return ERROR_GENERAL, was_changed, True

        # 4. Numeric input
        try:
            if '.' in raw_input:
                new_value = float(raw_input)
            else:
                new_value = int(raw_input)
            was_changed = self._values.get(name) != new_value
            return new_value, was_changed, False

        except ValueError:
            # 5. Text input
            new_value = raw_input
            was_changed = self._values.get(name) != new_value
            return new_value, was_changed, False


    def set(self, name: str, raw: str) -> List[str]:
        """
        Sets the raw input for a cell and recalculates dependent values according to topological order.
        Returns cells whose value may have changed, in row-major order.
        """
        validated_name = self._validate_name(name)

        # Store old raw value to detect if the input itself changed
        old_raw = self._raw_values.get(validated_name, '')

        # Only proceed if the input actually changed (or if we are setting it for the first time)
        if old_raw == raw and self._raw_values.get(validated_name) != raw:
             return []

        self._raw_values[validated_name] = raw

        # 1. Identify the minimal set of cells that must be recalculated (the affected set)
        # This includes the changed cell and all cells that depend on it.
        dependent_cells = self.graph.all_dependents(validated_name) | {validated_name}

        # Initialize state tracking for this set() call
        newly_changed_cells: Dict[str, Any] = {} # {name: new_value}
        formula_cells_evaluated_this_set: Set[str] = set()

        # Track cells whose dependencies have settled, ready for calculation in the next pass
        ready_to_calculate: Set[str] = set()

        # Initialize the calculation order queue based on dependencies
        # Start by queuing cells whose dependencies are either external (not tracked) or are the cell itself
        # For simplicity and compliance with "after all of the cells it refers to are up to date", 
        # we iterate until no changes occur, simulating the required order by prioritizing ready cells.

        # Mark all dependent cells as candidates for evaluation
        candidates = set(dependent_cells)

        # Set up initial state for iteration: Only cells that depend on nothing *within* the set are ready initially
        for cell_name in candidates:
            precedents = self.graph.precedents(cell_name)
            # A cell is ready if all its precedents are either:
            # a) Not in the affected set (their value is stable from before this set() call)
            # b) Or, the precedent is the changed cell (validated_name)

            # For the first pass, we assume anything not in the set is stable, and the changed cell is the starting point.
            is_ready = True
            for p in precedents:
                if p in candidates and p != validated_name:
                    is_ready = False
                    break
            if is_ready:
                ready_to_calculate.add(cell_name)


        # --- Iterative Recalculation (Simulating Topological Sort/Order) ---

        while ready_to_calculate:
            # Process cells in row-major order for determinism
            sorted_ready = sorted(list(ready_to_calculate), key=lambda n: (int(n[1:]), n[0]))
            ready_to_calculate.clear()

            newly_evaluated_in_pass = set()

            for current_name in sorted_ready:
                # Check if this cell was already updated in a prior pass (shouldn't happen if ready_to_calculate is managed correctly)
                if current_name in newly_changed_cells:
                    continue

                # Calculate value
                new_value, was_changed, was_evaluated = self._recalculate_cell(current_name)

                # Update state for this set() call
                self._values[current_name] = new_value
                newly_changed_cells[current_name] = new_value

                if was_changed:
                    # If this cell's value changed, all its direct dependents must be checked next.
                    for dependent in self.graph.dependents(current_name):
                        if dependent in candidates and dependent not in newly_changed_cells:
                            # This dependent might now be ready to calculate because its dependency changed
                            pass 

                if was_evaluated:
                    formula_cells_evaluated_this_set.add(current_name)

                newly_evaluated_in_pass.add(current_name)

            # Determine next set of ready cells based on which dependencies settled

            # Re-evaluate readiness for all non-updated candidates based on the current state
            candidates_to_check_readiness = candidates - newly_changed_cells

            for cell_name in candidates_to_check_readiness:
                if cell_name in newly_changed_cells:
                    continue

                precedents = self.graph.precedents(cell_name)

                # Check if all precedents have either:
                # 1. Been evaluated/updated in this set() call (and thus their value is now stable for this pass)
                # 2. Not be part of the affected set (and thus their value is stable from the previous state)
                all_deps_settled = True
                for p in precedents:
                    if p in candidates and p not in newly_changed_cells and p not in {validated_name}:
                        # If a precedent is in the affected set but hasn't been evaluated yet, it's not settled.
                        all_deps_settled = False
                        break

                if all_deps_settled:
                    ready_to_calculate.add(cell_name)

        # 3. Update evaluation count (Rule 3)
        self.evaluations += len(formula_cells_evaluated_this_set)


        # 4. Return results in row-major order
        result_list = []
        all_relevant_names = sorted(list(newly_changed_cells.keys()), key=lambda n: (int(n[1:]), n[0]))

        for name in all_relevant_names:
            result_list.append(name)

        return result_list

    def get(self, name: str) -> Any:
        """Returns the calculated value of the cell."""
        validated_name = self._validate_name(name)
        return self._values.get(validated_name)

    def raw(self, name: str) -> str:
        """Returns the input string stored for the cell."""
        validated_name = self._validate_name(name)
        return self._raw_values.get(validated_name, '')

    def cells(self) -> List[str]:
        """Returns all non-empty cells in row-major order."""
        all_names = list(self._raw_values.keys())

        # Filter based on non-empty raw input
        non_empty_names = [n for n in all_names if self._raw_values[n] != '']

        def sort_key(name):
            # Assumes valid name format due to filtering by self._raw_values keys
            row = int(name[1:])
            col = name[0]
            return (row, col)

        return sorted(non_empty_names, key=sort_key)
