# sheet/graph.py
from typing import Set, Dict

class DependencyGraph:
    """
    Records dependencies: which cells a formula refers to (precedents),
    and which cells refer to a given cell (dependents).
    """
    def __init__(self):
        self._precedents: Dict[str, Set[str]] = {}
        self._dependents: Dict[str, Set[str]] = {}

    def set_dependencies(self, cell: str, precedents: Set[str]):
        """Replaces cell's precedents and rebuilds dependents."""
        self._precedents[cell] = precedents
        self._rebuild_dependents()

    def precedents(self, cell: str) -> Set[str]:
        """Returns the direct cells this cell refers to."""
        return self._precedents.get(cell, set())

    def dependents(self, cell: str) -> Set[str]:
        """Returns cells that directly refer to this cell."""
        return self._dependents.get(cell, set())

    def all_dependents(self, cell: str) -> Set[str]:
        """
        Returns every cell that refers to 'cell' directly or indirectly.
        Excludes 'cell' itself unless 'cell' is on a cycle.
        """
        if cell not in self._dependents:
            return set()

        # BFS traversal starting from direct dependents
        queue = list(self._dependents[cell])
        visited = set(self._dependents[cell])

        while queue:
            current = queue.pop(0)
            # Add everything that depends on 'current'
            for dependent in self._dependents.get(current, set()):
                if dependent not in visited:
                    visited.add(dependent)
                    queue.append(dependent)

        return visited

    def cycle_cells(self) -> Set[str]:
        """
        Finds every cell that lies on a cycle using DFS.
        """
        visited: Set[str] = set()
        recursion_stack: Set[str] = set()
        on_cycle: Set[str] = set()

        def dfs(cell: str):
            visited.add(cell)
            recursion_stack.add(cell)

            for precedent in self.precedents(cell):
                # Only recurse on cells that are actively tracked in the graph
                if precedent not in self._precedents:
                    continue 

                if precedent in recursion_stack:
                    # Cycle detected: 'precedent' is an ancestor in the current path.
                    # Mark both the ancestor and the current cell as being on a cycle path.
                    on_cycle.add(cell)
                    on_cycle.add(precedent) # Mark the cycle start too

                if precedent not in visited:
                    dfs(precedent)

                    # If the recursive call found a cycle involving the precedent, 
                    # this cell is part of the dependency chain leading back to it.
                    if precedent in on_cycle:
                        on_cycle.add(cell)

            recursion_stack.remove(cell)

        # Iterate over all cells known to the graph
        all_cells = set(self._precedents.keys())
        for cell in all_cells:
            if cell not in visited:
                dfs(cell)

        return on_cycle

    def _rebuild_dependents(self):
        """Reconstructs the full dependents map from the precedents map."""
        self._dependents.clear()
        for cell, precedents_set in self._precedents.items():
            for precedent in precedents_set:
                if precedent not in self._dependents:
                    self._dependents[precedent] = set()
                self._dependents[precedent].add(cell)
