# resolve/solver.py
from typing import Dict, List, Tuple, Optional
from .versions import Version, Range
from .index import PackageIndex

class ResolutionError(Exception):
    def __init__(self, package: str, explanation: str):
        self.package = package
        self.explanation = explanation
        super().__init__(self.explanation)

    def __str__(self):
        return self.explanation

def resolve(index: PackageIndex, requirements: Dict[str, str]) -> Dict[str, Version]:
    """
    Resolves package dependencies using a backtracking depth-first search.
    """

    # 1. Initialization
    # Order: list of package names to resolve, sorted alphabetically
    order = sorted(requirements.keys())

    # Selected: {name: Version} tracking the result
    selected: Dict[str, Version] = {}

    # Recursive backtracking function
    def dfs(current_order: List[str], current_selected: Dict[str, Version]) -> Optional[Dict[str, Version]]:

        # 1. Find the next package to resolve
        next_package_name = None
        for pkg_name in current_order:
            if pkg_name not in current_selected:
                next_package_name = pkg_name
                break

        # Success condition: All required packages are selected
        if next_package_name is None:
            return current_selected.copy()

        pkg_name = next_package_name

        # 2. Determine all constraints for pkg_name
        constraints: List[Tuple[Range, str]] = [] # (Range, Requirer_String)

        # Constraint 1: Root requirements
        if pkg_name in requirements:
            try:
                root_range = Range(requirements[pkg_name])
                constraints.append((root_range, f"<root> requires {pkg_name} {root_range.normalized_spec}"))
            except ValueError as e:
                # This should have been caught during initial setup, but safety first
                raise ResolutionError(pkg_name, f"Initial requirement error: {e}")

        # Constraints 2: Requirements from already selected packages
        for name, selected_version in current_selected.items():
            try:
                reqs = index.requirements(name, selected_version)
                if pkg_name in reqs:
                    range_spec = reqs[pkg_name]
                    # Requirer format: name version
                    requirer_str = f"{name} {selected_version.text}"
                    constraints.append((range_spec, f"{requirer_str} requires {pkg_name} {range_spec.normalized_spec}"))
            except KeyError:
                # Should never happen if current_selected only contains valid selections
                pass

        # 3. Get candidates (newest first)
        candidates = index.versions(pkg_name)

        # 4. Iterate through candidates (Backtracking loop)
        for candidate_v in candidates:

            # --- Acceptance Check ---

            # Check 4a: Does candidate satisfy all explicit constraints?
            is_acceptable_by_constraints = True
            for range_spec, _ in constraints:
                if not range_spec.contains(candidate_v):
                    is_acceptable_by_constraints = False
                    break

            if not is_acceptable_by_constraints:
                # If it fails here, it contributes to the failure explanation
                continue

            # Check 4b: Does candidate satisfy transitive constraints from already selected dependencies?
            is_acceptable_by_deps = True
            candidate_reqs = index.requirements(pkg_name, candidate_v)

            for dep_name, dep_range in candidate_reqs.items():
                if dep_name in current_selected:
                    selected_dep_v = current_selected[dep_name]
                    if not dep_range.contains(selected_dep_v):
                        is_acceptable_by_deps = False
                        break

            if not is_acceptable_by_deps:
                # If it fails here, it contributes to the failure explanation
                continue

            # --- Candidate is Acceptable: Try selection ---

            new_selected = current_selected.copy()
            new_selected[pkg_name] = candidate_v

            new_order = list(current_order)

            # Add new, unselected dependencies to the end of the resolution order (alphabetically)
            deps_to_add = []
            for dep_name in candidate_reqs:
                if dep_name not in current_selected and dep_name not in new_order:
                    deps_to_add.append(dep_name)

            # Append new dependencies in alphabetical order
            deps_to_add.sort()
            new_order.extend(deps_to_add)

            # Recurse
            result = dfs(new_order, new_selected)

            if result is not None:
                # Success found down this path
                return result

        # --- Failure for pkg_name ---
        # If the loop finishes without returning, no candidate worked. Generate error.

        failure_lines = ["cannot resolve {pkg_name}".format(pkg_name=pkg_name)]

        # 1. Add constraints list
        for range_spec, requirer_str in constraints:
            failure_lines.append("  {requirer_str}".format(requirer_str=requirer_str))

        # 2. Check known versions vs exclusions
        if not candidates:
            failure_lines.append("  no versions of {pkg_name} are known".format(pkg_name=pkg_name))
        else:
            # Check every candidate against constraints and selected dependencies
            for candidate_v in candidates:

                # Re-check constraints (Necessary for explanation formatting)
                constraint_violated = False
                for range_spec, _ in constraints:
                    if not range_spec.contains(candidate_v):
                        constraint_violated = True
                        break

                if constraint_violated:
                    failure_lines.append(f"  {pkg_name} {candidate_v.text} is excluded by the constraints")
                    continue

                # If constraints are met, check dependency conflicts
                conflicting_dependency = None
                candidate_reqs = index.requirements(pkg_name, candidate_v)

                for dep_name in sorted(candidate_reqs.keys()): # Check dependencies in alphabetical order
                    dep_range = candidate_reqs[dep_name]
                    if dep_name in current_selected:
                        selected_dep_v = current_selected[dep_name]
                        if not dep_range.contains(selected_dep_v):
                            conflicting_dependency = dep_name
                            break

                if conflicting_dependency:
                    failure_lines.append(f"  {pkg_name} {candidate_v.text} requires {conflicting_dependency} {index.requirements(pkg_name, candidate_v)[conflicting_dependency].normalized_spec}, but {conflicting_dependency} {current_selected[conflicting_dependency].text} is selected")
                # Note: If constraints are met and no selected dependencies conflict, we implicitly skip logging it, 
                # because the failure implies *all* candidates failed.

        explanation = "\n".join(failure_lines)
        raise ResolutionError(pkg_name, explanation)


    # Initial call setup
    try:
        return dfs(order, selected)
    except ResolutionError as e:
        raise e
    except Exception as e:
        # Catch unexpected errors during execution path (e.g., internal logic error)
        raise ResolutionError("internal", f"Unexpected error during resolution: {e}")
