            try:
                target_version = Version(target_text)
                return version >= target_version
            except ValueError:
                return False

        if constraint.startswith("<="):
            target_text = constraint[2:]
            try:
                target_version = Version(target_text)
                return version <= target_version
            except ValueError:
                return False

        if constraint.startswith(">"):
            target_text = constraint[1:]
            try:
                target_version = Version(target_text)
                return version > target_version
            except ValueError:
