import re
from typing import Tuple

class Version:
    VERSION_REGEX = re.compile(r"^(\d+)\.(\d+)\.(\d+)$")

    def __init__(self, text: str):
        match = self.VERSION_REGEX.match(text)
        if not match:
            raise ValueError(f"Invalid version format: {text}")

        parts = [int(p) for p in match.groups()]
        self.major, self.minor, self.patch = parts
        self.text = text

    def __lt__(self, other):
        return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

    def __le__(self, other):
        return (self.major, self.minor, self.patch) <= (other.major, other.minor, other.patch)

    def __gt__(self, other):
        return (self.major, self.minor, self.patch) > (other.major, other.minor, other.patch)

    def __ge__(self, other):
        return (self.major, self.minor, self.patch) >= (other.major, other.minor, other.patch)

    def __eq__(self, other):
        return self.major == other.major and self.minor == other.minor and self.patch == other.patch

    def __hash__(self):
        return hash((self.major, self.minor, self.patch))

    def __str__(self):
        return f"{self.major}.{self.minor}.{self.patch}"

    @property
    def major(self):
        return self.major

    @property
    def minor(self):
        return self.minor

    @property
    def patch(self):
        return self.patch

class Range:
    def __init__(self, spec: str):
        self.original_spec = spec.strip()
        self.constraints = self._parse_spec(spec)
        self.normalized_spec = "".join(c.strip() for c in self.constraints)

    def _parse_spec(self, spec: str) -> list[str]:
        if not spec:
            raise ValueError("Empty range specification")

        raw_constraints = [c.strip() for c in spec.split(',')]

        parsed = []
        for rc in raw_constraints:
            # CRITICAL FIX: Check for empty constraint after stripping whitespace
            if not rc:
                 raise ValueError("Empty constraint found in range specification")

            # Handle *, ==, !=, >, >=, <, <=, ^, ~
            if rc == '*':
                parsed.append('*')
                continue

            match_exact = re.fullmatch(r"==(\d+)\.(\d+)\.(\d+)", rc)
            if match_exact:
                parsed.append(f"=={match_exact.group(1)}.{match_exact.group(2)}.{match_exact.group(3)}")
                continue

            match_op = re.fullmatch(r"(!=|>=|<=|>|<)(\d+)\.(\d+)\.(\d+)", rc)
            if match_op:
                op, M, m, p = match_op.groups()
                parsed.append(f"{op}{M}.{m}.{p}")
                continue

            match_caret = re.fullmatch(r"\^(\d+)\.(\d+)\.(\d+)", rc)
            if match_caret:
                M, m, p = match_caret.groups()
                parsed.append(f"^({M}.{m}.{p})")
                continue

            match_tilde = re.fullmatch(r"~(\d+)\.(\d+)\.(\d+)", rc)
            if match_tilde:
                M, m, p = match_tilde.groups()
                parsed.append(f"~({M}.{m}.{p})")
                continue

            # Handle un-prefixed versions (e.g., "1.2.3" becomes "==1.2.3")
            match_version = re.fullmatch(r"(\d+)\.(\d+)\.(\d+)", rc)
            if match_version:
                parsed.append(f"=={match_version.group(1)}.{match_version.group(2)}.{match_version.group(3)}")
                continue

            raise ValueError(f"Unknown operator or format in range constraint: {rc}")

        return parsed

    def contains(self, version: Version) -> bool:
        for constraint in self.constraints:
            if not self._check_constraint(constraint, version):
                return False
        return True

    def _check_constraint(self, constraint: str, version: Version) -> bool:
        if constraint == '*':
            return True

        # Check explicit version equality
        if constraint.startswith("=="):
            target_text = constraint[2:]
            try:
                target_version = Version(target_text)
                return version == target_version
            except ValueError:
                return False

        # Check operators (>, >=, <, <=, !=)
        if constraint.startswith("!="):
            target_text = constraint[2:]
            try:
                target_version = Version(target_text)
                return version != target_version
            except ValueError:
                return False

        if constraint.startswith(">="):
            target_text = constraint[2:]
            try:
                target_version = Version(target_text)
                return version >= target_version
            except ValueError:
                return False

        if constraint.startswith("<="):
            target_text = constraint[2:]
            try:
                target_version = Version(target_text)
                return version <= target_version
            except ValueError:
                return False

        if constraint.startswith(">"):
            target_text = constraint[1:]
            try:
                target_version = Version(target_text)
                return version > target_version
            except ValueError:
                return False

        if constraint.startswith("<"):
            target_text = constraint[1:]
            try:
                target_version = Version(target_text)
                return version < target_version
            except ValueError:
                return False

        # Handle caret (^) and tilde (~) ranges
        if constraint.startswith("^"):
            target_text = constraint[1:]
            try:
                base_v = Version(target_text)

                if base_v.major == 0 and base_v.minor == 0 and base_v.patch == 0:
                    # ^0.0.0 is >=0.0.0, <0.0.1
                    upper_bound = Version("0.0.1")
                    lower_bound = base_v
                elif base_v.major == 0:
                    # ^0.minor.patch is >=0.minor.patch, <0.(minor+1).0
                    next_minor = base_v.minor + 1
                    upper_bound = Version(f"0.{next_minor}.0")
                    lower_bound = base_v
                else:
                    # ^M.m.p is >=M.m.p, <(M+1).0.0
                    next_major = base_v.major + 1
                    upper_bound = Version(f"{next_major}.0.0")
                    lower_bound = base_v

                return lower_bound <= version < upper_bound

            except ValueError:
                return False

        if constraint.startswith("~"):
            target_text = constraint[1:]
            try:
                base_v = Version(target_text)

                if base_v.patch == 0:
                    # ~M.m.0 is >=M.m.0, <M.(m+1).0
                    next_minor = base_v.minor + 1
                    upper_bound = Version(f"{base_v.major}.{next_minor}.0")
                    lower_bound = base_v
                else:
                    # ~M.m.p is >=M.m.p, <M.m.(p+1)
                    next_patch = base_v.patch + 1
                    upper_bound = Version(f"{base_v.major}.{base_v.minor}.{next_patch}")
                    lower_bound = base_v

                return lower_bound <= version < upper_bound
            except ValueError:
                return False

        return False

    def __str__(self):
        return self.normalized_spec

    def __repr__(self):
        return f"Range('{self.original_spec}')"
