            for dep_name, spec in requires.items():
                try:
                    new_package_data[dep_name] = Range(spec)
                except ValueError as e:
                    raise ValueError(f"Bad requirement spec '{spec}' for {name}@{version_str}: {e}")

        self._packages[name][version_str] = new_package_data

    def versions(self, name: str) -> List[Version]:
        if name not in self._packages:
            return []

        versions_list = [Version(v_str) for v_str in self._packages[name]]
        # Return newest first
        return sorted(versions_list, reverse=True)

    def requirements(self, name: str, version: Version) -> Dict[str, Range]:
        if name not in self._packages or version.text not in self._packages[name]:
            raise KeyError(f"Package {name} version {version.text} not found in index.")

        return self._packages[name][version.text]

    @classmethod
    def from_dict(cls, data: Dict) -> 'PackageIndex':
        index = cls()
        for name, versions_data in data.items():
            if name not in index._packages:
                index._packages[name] = {}

            for version_str, reqs_data in versions_data.items():
                try:
                    v = Version(version_str)
                except ValueError:
                    raise ValueError(f"Bad version '{version_str}' in input data for {name}")

                if version_str in index._packages[name]:
                    raise ValueError(f"Duplicate version {version_str} for {name} in input data.")

                req_ranges: Dict[str, Range] = {}
                for dep, spec in reqs_data.items():
                    try:
