    def contains(self, version: Version) -> bool:
        if not self._constraints:
            return False

        for op, target_version in self._constraints:
            if op == '==':
                if not (version == target_version): return False
            elif op == '!=':
                if version == target_version: return False
            elif op == '>':
                if not (version > target_version): return False
            elif op == '<':
                if not (version < target_version): return False
            elif op == '>=':
                if not (version >= target_version): return False
            elif op == '<=':
                if not (version <= target_version): return False
            elif op == '>=' or op == '<=':
                # Handled above, but defensive check
                pass
            elif op == '*':
                # Always true
                pass
            else:
                # Should not happen
                return False
        return True

    def __contains__(self, version: Version) -> bool:
        return self.contains(version)

    def __str__(self) -> str:
        # Remove all whitespace for canonical representation
        return "".join(str(c) for c in self._constraints if c[1] is not None)

    def __repr__(self):
        return f"Range('{self._spec}')"
