# resolve/versions.py

import re
from typing import Tuple

class Version:
    def __init__(self, text: str):
        match = re.fullmatch(r"(\d+)\.(\d+)\.(\d+)", text)
        if not match:
            raise ValueError(f"Invalid version format: {text}")

        try:
            self.major = int(match.group(1))
            self.minor = int(match.group(2))
            self.patch = int(match.group(3))
        except ValueError:
            raise ValueError(f"Version components must be integers: {text}")

    def __lt__(self, other):
        return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

    def __gt__(self, other):
        return (self.major, self.minor, self.patch) > (other.major, other.minor, other.patch)

    def __eq__(self, other):
        return isinstance(other, Version) and self.major == other.major and self.minor == other.minor and self.patch == other.patch

    def __hash__(self):
        return hash((self.major, self.minor, self.patch))

    def __str__(self):
        return f"{self.major}.{self.minor}.{self.patch}"

    def __repr__(self):
        return f"Version('{str(self)}')"

class Range:
    # Stores constraints as (operator, Version) tuples
    # Operator can be: '==', '!=', '>', '<', '>=', '<=', '*', '^', '~' (internal markers)
    # We store the parsed constraint object/value for easy checking.

    def __init__(self, spec: str):
        self._original_spec = spec.strip()
        self._constraints: List[Tuple[str, Version]] = []
        self._parse_spec(spec)

    def _parse_version_from_constraint(self, constraint_str: str) -> Version:
        # Extracts the version part from a constraint string
        match = re.search(r"(\d+\.\d+\.\d+)$", constraint_str)
        if not match:
            # Fallback for cases where operator is attached (e.g., ">=1.2.3")
            match = re.search(r"(\d+\.\d+\.\d+)$", constraint_str)
            if not match:
                raise ValueError(f"Could not parse version from constraint: {constraint_str}")
        return Version(match.group(1))

    def _parse_spec(self, spec: str):
        if not spec:
            raise ValueError("Range specification cannot be empty")

        spec = spec.strip()

        if spec == '*':
            self._constraints = [('*', None)]
            return

        constraint_strs = [c.strip() for c in spec.split(',')]

        for cs in constraint_strs:
            if not cs:
                raise ValueError("Empty constraint found in specification")

            cs_lower = cs.lower()

            if cs_lower == '*':
                self._constraints.append(('*', None))
                continue

            # 1. Check for caret (^)
            if cs_lower.startswith('^'):
                version_part = cs[1:].strip()
                try:
                    v = Version(version_part)

                    # Rule: ^X.Y.Z -> >=X.Y.Z, <(next major/minor/patch boundary)
                    if v.major > 0:
                        # ^1.2.3 -> >=1.2.3, <2.0.0
                        upper_bound = Version(f"{v.major + 1}.0.0")
                        self._constraints.append(('>=', v))
                        self._constraints.append(('<', upper_bound))
                    elif v.minor > 0:
                        # ^0.2.3 -> >=0.2.3, <0.3.0
                        upper_bound = Version(f"{v.major}.{v.minor + 1}.0")
                        self._constraints.append(('>=', v))
                        self._constraints.append(('<', upper_bound))
                    else: # v.major == 0 and v.minor == 0
                        # ^0.0.3 -> >=0.0.3, <0.0.4
                        upper_bound = Version(f"{v.major}.{v.minor}.{v.patch + 1}")
                        self._constraints.append(('>=', v))
                        self._constraints.append(('<', upper_bound))
                except ValueError as e:
                    raise ValueError(f"Invalid caret range '{cs}': {e}")

            # 2. Check for tilde (~)
            elif cs_lower.startswith('~'):
                version_part = cs[1:].strip()
                try:
                    v = Version(version_part)

                    # Rule: ~X.Y.Z -> >=X.Y.Z, <X.(Y+1).0 (or X.Y.(Z+1) if Z=9)
                    if v.patch < 9:
                        # ~1.2.3 -> >=1.2.3, <1.3.0
                        upper_bound = Version(f"{v.major}.{v.minor + 1}.0")
                    elif v.minor < 9:
                        # ~1.9.3 -> >=1.9.3, <1.10.0
                        upper_bound = Version(f"{v.major}.{v.minor + 1}.0")
                    else:
                        # ~1.9.9 -> >=1.9.9, <2.0.0
                        upper_bound = Version(f"{v.major + 1}.0.0")

                    self._constraints.append(('>=', v))
                    self._constraints.append(('<', upper_bound))
                except ValueError as e:
                    raise ValueError(f"Invalid tilde range '{cs}': {e}")

            # 3. Standard comparisons (==, !=, >, <, >=, <=)
            else:
                op = None
                version_str = cs

                if cs_lower.startswith("=="):
                    op = "=="
                    version_str = cs[2:].strip()
                elif cs_lower.startswith("!="):
                    op = "!="
                    version_str = cs[2:].strip()
                elif cs_lower.startswith(">="):
                    op = ">="
                    version_str = cs[2:].strip()
                elif cs_lower.startswith("<="):
                    op = "<="
                    version_str = cs[2:].strip()
                elif cs_lower.startswith(">"):
                    op = ">"
                    version_str = cs[1:].strip()
                elif cs_lower.startswith("<"):
                    op = "<"
                    version_str = cs[1:].strip()
                else:
                    # If no operator, it must be treated as an equality check if it's a valid version string
                    try:
                        v = Version(cs)
                        op = "=="
                        version_str = cs
                    except ValueError:
                        raise ValueError(f"Unrecognized operator or malformed constraint: {cs}")

                if op:
                    try:
                        v = Version(version_str)
                        self._constraints.append((op, v))
                    except ValueError:
                        raise ValueError(f"Bad version specified in constraint '{cs}'")

    def contains(self, version: Version) -> bool:
        for op, target_version in self._constraints:
            if op == '==':
                if not (version == target_version): return False
            elif op == '!=':
                if version == target_version: return False
            elif op == '>':
                if not (version > target_version): return False
            elif op == '<':
                if not (version < target_version): return False
            elif op == '>=':
                if not (version >= target_version): return False
            elif op == '<=':
                if not (version <= target_version): return False
            elif op == '*':
                pass
            # Caret/Tilde boundaries are handled by the explicit >= and < constraints generated
            else:
                # Should only hit this if internal state is inconsistent
                return False
        return True

    def __contains__(self, version: Version) -> bool:
        return self.contains(version)

    def __str__(self) -> str:
        # Reconstruct the canonical spec string, respecting operators and commas, removing all whitespace.
        parts = []
        for op, target_version in self._constraints:
            if op == '*':
                parts.append('*')
            elif op == '==':
                parts.append(f"=={target_version}")
            elif op == '!=':
                parts.append(f"!={target_version}")
            elif op == '>':
                parts.append(f">{target_version}")
            elif op == '<':
                parts.append(f"<{target_version}")
            elif op == '>=':
                parts.append(f">={target_version}")
            elif op == '<=':
                parts.append(f"<={target_version}")
            elif op == '^' or op == '~':
                # These are implicitly handled by the generated >= and < constraints,
                # but if we needed to represent them literally, we'd use the original spec part.
                # Since the goal is to show the resulting constraint set, we reconstruct the boundaries.
                pass 
            else:
                # For the purpose of string representation matching the original input style 
                # (or a clear derived standard), we stick to the explicit comparisons derived.
                pass

        # A more accurate reconstruction based on the rules (since ^/~ are broken into >=, <)
        # is complex. We simplify: if the original spec was not '*', we use the original spec, 
        # stripped of whitespace, as required by the prompt, since our internal representation
        # is the *result* of parsing it.
        return self._original_spec.replace(" ", "")


    def __repr__(self):
        return f"Range('{self._original_spec}')"
