        except ValueError:
            raise ValueError(f"Invalid version string provided: {version_str}")

        # Validate dependencies specs
        if requires:
            for dep_name, spec_str in requires.items():
                try:
                    # Range constructor validates the syntax of the spec string
                    Range(spec_str) 
                except ValueError as e:
                    raise ValueError(f"Invalid range spec '{spec_str}' for dependency {dep_name} of {name}@{version_str}: {e}")

        self._index[name][version_str] = requires if requires else {}

    def versions(self, name: str) -> List[Version]:
        if name not in self._index:
            return []

        version_strings = list(self._index[name].keys())

        versions = []
        for vs in version_strings:
            versions.append(Version(vs))

        # Sort descending (newest first)
        versions.sort(reverse=True)
        return versions

