        raw_deps = self._index[name][version_str]

        ranges = {}
        for dep_name, spec_str in raw_deps.items():
            try:
                # Range construction validates the stored spec
                ranges[dep_name] = Range(spec_str)
            except ValueError as e:
                raise RuntimeError(f"Internal error: Failed to parse stored range for {dep_name}@{version_str}: {e}")
        return ranges

    @classmethod
    def from_dict(cls, data: Dict[str, Dict[str, Dict[str, str]]]):
        index = cls()
        for name, versions_data in data.items():
            for version_str, requires_data in versions_data.items():
                try:
                    index.add(name, version_str, requires_data)
