from typing import Dict, List, Optional, Any
from .versions import Version, Range

class PackageIndex:
    def __init__(self):
        # Structure: {name: {version_string: {dep_name: range_spec_string, ...}}}
        self._index: Dict[str, Dict[str, Dict[str, str]]] = {}

    def add(self, name: str, version_str: str, requires: Optional[Dict[str, str]] = None):

        if name not in self._index:
            self._index[name] = {}

        if version_str in self._index[name]:
            raise ValueError(f"Version {version_str} for {name} already exists.")

        # Validate version format first
        try:
            Version(version_str)
        except ValueError:
            raise ValueError(f"Invalid version string provided: {version_str}")

        # Validate dependencies specs
        if requires:
            for dep_name, spec_str in requires.items():
                try:
                    # Range constructor validates the syntax of the spec string
                    Range(spec_str) 
                except ValueError as e:
                    raise ValueError(f"Invalid range spec '{spec_str}' for dependency {dep_name} of {name}@{version_str}: {e}")

        self._index[name][version_str] = requires if requires else {}

    def versions(self, name: str) -> List[Version]:
        if name not in self._index:
            return []

        version_strings = list(self._index[name].keys())

        versions = []
        for vs in version_strings:
            versions.append(Version(vs))

        # Sort descending (newest first)
        versions.sort(reverse=True)
        return versions

    def requirements(self, name: str, version: Version) -> Dict[str, Range]:
        if name not in self._index:
            raise KeyError(f"Package {name} not found in index.")

        version_str = str(version)
        if version_str not in self._index[name]:
            raise KeyError(f"Version {version_str} of {name} not found.")

        raw_deps = self._index[name][version_str]

        ranges = {}
        for dep_name, spec_str in raw_deps.items():
            try:
                # Range construction validates the stored spec
                ranges[dep_name] = Range(spec_str)
            except ValueError as e:
                raise RuntimeError(f"Internal error: Failed to parse stored range for {dep_name}@{version_str}: {e}")
        return ranges

    @classmethod
    def from_dict(cls, data: Dict[str, Dict[str, Dict[str, str]]]):
        index = cls()
        for name, versions_data in data.items():
            for version_str, requires_data in versions_data.items():
                try:
                    index.add(name, version_str, requires_data)
                except ValueError as e:
                    raise ValueError(f"Failed to build index from data for {name}@{version_str}: {e}")
        return index
